import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-h-001","clusterId":"H","werkstueckRef":"H.0","stufe":1,"question":"Welche Frage bringt dich in diesem Gespräch am ehesten weiter?","options":["Welche Denkfehler stecken in seiner Erklärung, und wie zeige ich sie ihm zuerst?","Welches Bedürfnis stillt ihm diese Erklärung, und wie nehme ich es zuerst ernst?","Wie belastbar sind die Quellen seines Forums, und wie prüfe ich sie zuerst mit ihm?","Welches Gegenbeispiel kann er nicht abtun, und wie bringe ich es zuerst ein?"],"correctIndex":1,"explanation":"Die Fakten sind schon zweimal abgeprallt, und das Gespräch dreht sich erkennbar um etwas anderes: Er erzählt von seinem Forum und seiner Entlassung, nicht von Zahlen. Das spricht dafür, dass der Glaube vor allem etwas anderes leistet, als Wissenslücken zu füllen. Eine Erklärung mit geheimem Plan ersetzt Zufall und Ohnmacht durch Absicht, und das Forum liefert Zugehörigkeit. Verschwörungsglaube wird laut Douglas, Sutton und Cichocka (2017) von epistemischen, existenziellen und sozialen Motiven angetrieben; die fünf Versprechen Sinn, Kontrolle, Einfachheit, Gemeinschaft und Selbstwert lassen sich diesen Motivgruppen zuordnen. Wer das Bedürfnis dahinter zuerst anerkennt, bleibt im Gespräch. Ob der Glaube es auf Dauer wirklich stillt, ist eine andere Frage: Für viele ist er eher verlockend als befriedigend. Die Denkfehler zu benennen klingt sinnvoll, trifft ihn aber als Kritik an der Person, solange das Bedürfnis dahinter unbeachtet bleibt. Die Quellen des Forums zu prüfen hilft, wenn man sich um Belege streitet, hier geht es aber nicht um Belege. Ein weiteres Gegenbeispiel wäre der dritte Anlauf mit demselben Mittel, das schon zweimal abgeprallt ist.","coreRule":"⚡ Wer einen Irrglauben verstehen will, fragt zuerst, welchen Durst er stillt.","quote":"","quoteLabel":"","beleg":"Werkstück H.0 (Kernidee; Die fünf großen Versprechen; Das Härten im Feuer, Aktivierungs-Frage); Fn. gl-h-beduerfnisse (Douglas/Sutton/Cichocka 2017, S. 538)","status":"entwurf","scenario":"Dein Onkel ist überzeugt, hinter den steigenden Preisen stecke ein geheimer Plan weniger Mächtiger. Du hast ihm zweimal Statistiken zu Lieferketten und Energiepreisen gezeigt. Er winkt ab, wird gereizt und erzählt stattdessen begeistert von seinem Online-Forum, in dem sich alle „endlich verstanden“ fühlen. Seit seiner Entlassung im letzten Jahr beschäftigt ihn das Thema fast täglich.","kurz":"Zweimal sind Zahlen abgeprallt, und er spricht von Forum und Entlassung. Das spricht dafür, dass die Erklärung ihm vor allem etwas anderes gibt als Wissen: Absicht statt Ohnmacht, Zugehörigkeit. Wer dieses Bedürfnis zuerst ernst nimmt, bleibt im Gespräch.","prueffrage":"Wovon redet er eigentlich begeistert, wenn die Statistiken schon abgeprallt sind?","rueckmeldung":[{"option":0,"text":"Denkfehler gibt es in seiner Erklärung tatsächlich, nur kommt es auf die Reihenfolge an. Solange sein Bedürfnis dahinter unbeachtet bleibt, trifft das Benennen ihn als Kritik an der Person, und die Fakten prallen weiter ab."},{"option":2,"text":"Quellen zu prüfen hilft, wenn man sich um Belege streitet. Hier geht es aber erkennbar nicht um Belege: Er erzählt vom Forum, in dem er sich verstanden fühlt, und von seiner Entlassung, nicht von Zahlen."},{"option":3,"text":"Ein Gegenbeispiel klingt anders als eine Statistik, ist aber derselbe Weg über Fakten, der schon zweimal abgeprallt ist. So wäre es der dritte Anlauf mit demselben Mittel, ohne dass sich am Anlass des Glaubens etwas ändert."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Douglas, Sutton & Cichocka (2017): The Psychology of Conspiracy Theories. Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"4","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"6caa1921312a4f45"}},{"id":"qx-h-002","clusterId":"H","werkstueckRef":"H.0","stufe":2,"question":"Welcher Gesprächsanfang ist am wahrscheinlichsten hilfreich, wenn du das Gespräch offen halten und zugleich die Entscheidung auf eine gute Grundlage stellen willst?","scenario":"Deine Schwägerin sagt, sie lasse ihr Kind nicht impfen, weil sie Angst hat, die falsche Entscheidung zu treffen.","options":["„Du willst das Beste für dein Kind, das kenne ich von mir auch. Bei meinem Kind hat die Impfung nie Probleme gemacht, du wirst sehen, dass es gut geht.“","„Du willst das Beste für dein Kind und fürchtest eine Fehlentscheidung. Das ist ganz allein deine Entscheidung, und ich mische mich da nicht ein.“","„Du willst das Beste für dein Kind und fürchtest eine Fehlentscheidung. Ich erkläre dir kurz, wie die Impfung wirkt, dann kannst du dich entscheiden.“","„Du willst das Beste für dein Kind und fürchtest eine Fehlentscheidung. Lass uns gemeinsam anschauen, was für und was gegen die Impfung spricht.“"],"correctIndex":3,"explanation":"Hinter der Entscheidung steht hier erkennbar ein Bedürfnis: Sicherheit und das Gefühl, keine folgenschwere Fehlentscheidung zu treffen. Der Gesprächsanfang, der die Angst als Wunsch nach der richtigen Entscheidung aufgreift und zum gemeinsamen Prüfen von Für und Wider einlädt, erkennt das Bedürfnis an, ohne dem Verzicht auf die Impfung zuzustimmen. So bleibt das Gespräch offen, und die Sache selbst kann überhaupt erst zur Sprache kommen. Eine kurze Sachauskunft klingt hilfsbereit, beantwortet aber nicht die Sorge, die hinter der Entscheidung steht. Die eigene gute Erfahrung kann beruhigen, ersetzt aber keine Prüfung ihrer Gründe und macht ihre Angst klein. Sich ganz herauszuhalten achtet ihre Selbstbestimmung, lässt sie mit der Angst aber allein und stellt die Entscheidung nicht auf eine bessere Grundlage.","coreRule":"⚡ Erst das Bedürfnis hinter einer Überzeugung anerkennen, dann gemeinsam die Sache prüfen.","beleg":"Werkstück H.0 (Anwendung & Relevanz: ‚Statt die Überzeugung anzugreifen, adressiere das Bedürfnis‘)","status":"entwurf","kurz":"Wer die Angst als Wunsch nach der richtigen Entscheidung aufgreift und zum gemeinsamen Abwägen einlädt, hält das Gespräch offen und bringt die Sache zur Sprache. Der naheliegende Fehler ist, nur zu beruhigen, zu informieren oder zu schweigen.","prueffrage":"Wie würdest du an ihrer Stelle auf einen Satz reagieren, der deine Sorge gleich zu Beginn für unbegründet oder für erledigt erklärt?","rueckmeldung":[{"option":0,"text":"Deine gute Erfahrung kann beruhigen, und der erste Satz nimmt ihr Anliegen ernst. Eine einzelne Erfahrung prüft aber keine Gründe und macht ihre Angst klein, statt sie ernst zu nehmen."},{"option":1,"text":"Hier wird ihre Selbstbestimmung geachtet, das ist ein echter Pluspunkt. Wer sich aber ganz heraushält, lässt sie mit ihrer Angst allein, und die Entscheidung steht danach auf keiner besseren Grundlage als vorher."},{"option":2,"text":"Eine kurze Erklärung klingt hilfsbereit und kann nützlich sein. Sie beantwortet aber nicht die Sorge hinter der Entscheidung, nämlich nichts Falsches zu tun, und macht sie eher zur Zuhörerin als zur Mitprüfenden."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Gagneur, A. (2020): Motivational interviewing: A powerful tool to address vaccine hesitancy. Canada Communicable Disease Report 46(4), 93–97","oeffentlich":true,"url":"https://www.canada.ca/en/public-health/services/reports-publications/canada-communicable-disease-report-ccdr/monthly-issue/2020-46/issue-4-april-2-2020/article-6-canvax-addressing-vaccine-hesitancy.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook, Abschnitt „How to talk to a conspiracy theorist“","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"fa917ad70e4d82a6"}},{"id":"qx-h-003","clusterId":"H","werkstueckRef":"H.0","stufe":3,"question":"Du liest in einem Forum den Satz: „Wer einem Gruppenmitglied Fakten gegen dessen Überzeugung zeigt, bestärkt es damit nur noch mehr in seinem Irrtum.“ Die Debatte dreht sich im Kern um Zugehörigkeit und Identität. Was ist an dieser Behauptung am ehesten problematisch?","options":["Sie überschätzt den Effekt: Fakten verhärten in Identitätsdebatten oft die Fronten, dass sie den Irrtum aber aktiv bestärken, kommt selten vor.","Sie bekämpft ein Zerrbild: Sie stellt die Gegenseite verzerrt dar, um sie leichter widerlegen zu können (Strohmann-Argument).","Sie dreht sich im Kreis: Sie setzt voraus, dass die Überzeugung falsch ist, und folgert daraus, dass Fakten nichts bewirken (Zirkelschluss).","Sie malt eine Kette immer schlimmerer Folgen aus, obwohl die einzelnen Schritte nicht belegt sind (Dammbruchargument oder Slippery Slope)."],"correctIndex":0,"explanation":"Wenn es im Kern um Identität und Zugehörigkeit geht, erlebt die Person Fakten oft als Angriff auf ihre Gruppe, und die Fronten verhärten sich. Daraus folgt aber nicht, dass Fakten den Irrtum aktiv verstärken: Ein solcher Backfire-Effekt ist empirisch selten. Die Behauptung verwechselt also „wirkt oft nicht“ mit „wirkt ins Gegenteil“. Fakten sind in solchen Debatten häufig nicht die richtige Währung, aber nicht per se schädlich. Wer das Bedürfnis hinter dem Glauben anspricht, hat oft bessere Chancen als mit einem weiteren Faktenstrom. Ein Strohmann liegt nicht vor, denn die Behauptung stellt keine Gegenposition dar. Ein Zirkelschluss liegt nicht vor, denn sie behauptet eine Wirkung, statt sie aus der bloßen Annahme eines Irrtums abzuleiten. Und eine Kette immer schlimmerer Folgen beschreibt sie nicht, es geht um einen einzelnen Effekt.","coreRule":"⚡ In Identitätsdebatten sind Fakten allein oft nicht die richtige Währung und verhärten die Fronten, bestärken den Irrtum aber nur selten (Backfire-Effekt).","beleg":"Werkstück H.0 (Anwendung & Relevanz: ‚Erkennen, dass Fakten oft nicht die richtige Währung sind‘)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Identitätsdebatten verhärten sich oft, wenn Fakten kommen, weil sie als Angriff auf die Gruppe erlebt werden. Der Fehler liegt darin, „wirkt oft nicht“ mit „wirkt ins Gegenteil“ gleichzusetzen: Ein echter Backfire-Effekt ist selten.","prueffrage":"Wie oft halten Menschen nach einer Korrektur tatsächlich stärker am Irrtum fest als vorher?","rueckmeldung":[{"option":1,"text":"Debatten über Identität werden tatsächlich oft verzerrt geführt, daher liegt der Verdacht nahe. Der Satz stellt aber keine Gegenposition dar, die er zerlegt, sondern behauptet selbst eine Wirkung von Fakten. Zu prüfen ist diese Wirkung, nicht eine Darstellung der Gegenseite."},{"option":2,"text":"Weil das Wort „Irrtum“ im Satz steckt, wirkt er wie eine Annahme, die das Ergebnis vorwegnimmt. Er behauptet aber eine Wirkung, die man an der Wirklichkeit prüfen kann, und leitet sie nicht allein aus dieser Annahme ab. Die Schwäche liegt in der Überdehnung, nicht in einem Kreis."},{"option":3,"text":"Die Aussage klingt nach Warnung und malt Schaden aus, das erinnert an ein Dammbruchargument. Es fehlt aber die Kette aus mehreren Schritten, die jeweils zum nächsten führen sollen. Behauptet wird nur ein einzelner Effekt, und genau dessen Stärke trägt nicht."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Nyhan, B. (2021): Why the backfire effect does not explain the durability of political misperceptions. PNAS 118(15)","oeffentlich":true,"doi":"10.1073/pnas.1912440117","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Wood, T. & Porter, E. (2019): The Elusive Backfire Effect: Mass Attitudes' Steadfast Factual Adherence. Political Behavior 41(1), 135–163","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"5ed528cf1bd3350a"}},{"id":"qx-h-004","clusterId":"H","werkstueckRef":"H.0","stufe":4,"question":"Was ist an der Aussage deines Bekannten problematisch?","scenario":"Ein Bekannter sagt: „Bei Verschwörungsgläubigen sind Belege sinnlos. Man kann nur ihre Bedürfnisse bedienen.“ Du weißt, dass in einem großen Experiment von 2024 ein Sprachmodell in Einzelgesprächen mit gut zugeschnittenen Belegen auf die jeweiligen Überzeugungen der Teilnehmenden einging. Der Verschwörungsglaube der Teilnehmenden ließ danach nach – auch bei denen, die fest überzeugt waren.","options":["Sie ist zu abwertend: Sie unterstellt Verschwörungsgläubigen mangelnde Intelligenz, obwohl auch kluge Menschen solchen Erzählungen anhängen.","Sie ist zu pauschal: Das Experiment zeigt, dass auch gut zugeschnittene Belege den Glauben lockern können, selbst bei fest Überzeugten.","Sie ist zu einseitig, weil sie die Bedürfnisse nach Sinn, Kontrolle und Gemeinschaft übergeht, die den Glauben in erster Linie tragen.","Sie ist stichhaltig: Ein einzelnes Experiment, auch ein großes, entscheidet nichts, solange es nicht von anderen Gruppen wiederholt wurde."],"correctIndex":1,"explanation":"Dass Verschwörungsglaube oft psychologische Bedürfnisse nach Sinn, Kontrolle, Gemeinschaft oder Selbstwert stillt, ist gut begründet, und dann ist es klug, ein Bedürfnis zuerst ernst zu nehmen. Daraus folgt aber nicht, dass Belege wirkungslos sind. Das widerlegt schon ein einziges gut gemachtes Gegenbeispiel: Im Experiment von 2024 lockerten gut zugeschnittene Belege den Glauben, auch bei fest Überzeugten. Die Aussage „Belege sind sinnlos“ ist ein Alles-oder-nichts-Schluss aus einer richtigen Teilbeobachtung. Die anderen Antworten passen nicht: Der Bekannte unterstellt keine mangelnde Intelligenz und übergeht die Bedürfnisse nicht, er hebt sie im Gegenteil allein hervor. Und weil seine Aussage ein Allsatz ist („sinnlos“), genügt ein gut gemachtes Gegenbeispiel, um sie zu entkräften; die Wiederholung durch andere Gruppen wäre erst nötig, um die Wirkung der Belege genauer zu bestimmen.","coreRule":"⚡ Bedürfnisse ernst nehmen, aber Belege nicht pauschal für wirkungslos erklären: Ein einziges gut belegtes Gegenbeispiel genügt gegen „nie“ und „sinnlos“.","beleg":"Werkstück H.0 (Anwendung & Relevanz: ‚Ein besseres Angebot machen‘; Verweis auf Anhang VII.1; keine Fußnote für diese Aussage)","status":"entwurf","kurz":"Aus der richtigen Beobachtung, dass der Glaube oft Bedürfnisse stillt, macht der Bekannte ein Alles-oder-nichts: Belege seien sinnlos. Ein gut gemachtes Gegenbeispiel genügt, um das zu entkräften, und das Experiment von 2024 liefert es auch bei fest Überzeugten.","prueffrage":"Wer nahm am Experiment von 2024 teil, und was geschah mit dem Glauben der Teilnehmenden nach den Gesprächen?","rueckmeldung":[{"option":0,"text":"Dass auch kluge Menschen solchen Erzählungen anhängen, stimmt. Nur unterstellt der Bekannte nichts über Intelligenz: Er sagt etwas über die Wirkung von Belegen, und genau dort liegt der Fehler."},{"option":2,"text":"Die Bedürfnisse nach Sinn, Kontrolle und Gemeinschaft sind oft wichtig, und der Gedanke liegt deshalb nahe. Der Bekannte übergeht sie aber nicht, er hebt sie als Einziges hervor. Nicht tragend ist sein Schluss, Belege seien deshalb wirkungslos."},{"option":3,"text":"Ein einzelnes Experiment reicht für genaue Aussagen über die Wirkung von Belegen nicht aus, das stimmt. Eine Aussage wie „sinnlos“ gilt aber für alle Fälle und fällt schon durch ein gut gemachtes Gegenbeispiel."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Douglas, Sutton & Cichocka (2017): The Psychology of Conspiracy Theories. Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"},{"typ":"doi","kurz":"Costello, Pennycook & Rand (2024): Durably reducing conspiracy beliefs through dialogues with AI. Science 385(6714), eadq1814","oeffentlich":false,"doi":"10.1126/science.adq1814","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"479b7057919ccecb"}},{"id":"qx-h-005","clusterId":"H","werkstueckRef":"H.0.1","stufe":1,"question":"Welche Deutung des Ergebnisses ist angemessen, und wie sicher darfst du dir dabei sein?","options":["Der Gedanke an den eigenen Tod verstärkt das Bedürfnis, die eigene Weltanschauung zu verteidigen; bei 22 Personen und gescheiterten Wiederholungen verwandter Befunde ist das aber nur eine vorläufige Vermutung.","Die Todesfragen setzten einen Zahlenanker, an dem sich die Richter bei der Kaution orientierten; bei 22 Personen und gescheiterten Wiederholungen verwandter Befunde ist das aber nur eine vorläufige Vermutung.","Ein Vorurteil gegen die Angeklagte machte die Richter strenger, sobald sie über deren Kaution entschieden; bei 22 Personen und gescheiterten Wiederholungen verwandter Befunde ist das aber nur eine vorläufige Vermutung.","Die Fragen ermüdeten die Richter, sodass sie weniger sorgfältig abwogen und härter entschieden; bei 22 Personen und gescheiterten Wiederholungen verwandter Befunde ist das aber nur eine vorläufige Vermutung."],"correctIndex":0,"explanation":"Ein auffälliger Unterschied zwischen zwei Gruppen verlangt zwei Prüfungen: Welche Erklärung passt zu den Daten, und wie belastbar sind die Daten selbst? Dass die Todeserinnerung das Bedürfnis weckt, die eigene Weltanschauung zu verteidigen, ist eine naheliegende Deutung, denn die mutmaßliche Prostituierte verstieß gegen die Normen dieser Weltanschauung. Bei nur 22 Richtern und gescheiterten Wiederholungsversuchen zu verwandten Todeserinnerungs-Befunden (das Richter-Experiment selbst wurde nicht wiederholt) bleibt es aber eine vorläufige Vermutung und keine gesicherte Tatsache. Ein Zahlenanker passt nicht, denn die Fragen enthielten keine Zahl, an der sich die Richter hätten orientieren können. Ein Vorurteil gegen die Angeklagte erklärt keinen Unterschied zwischen den Gruppen, denn beide urteilten über denselben Fall. Und zwei kurze Fragen sind kaum geeignet, jemanden so zu ermüden, dass sich daraus der Unterschied erklärte.","coreRule":"⚡ Passende Erklärung nennen, Gewissheit an der Datenlage messen: Kleine Stichprobe plus gescheiterte Wiederholungen heißt vorläufig.","beleg":"Werkstück H.0.1 (Kernidee: zwei Hauptstrategien)","status":"entwurf","scenario":"In einem Experiment bekommen Richter vor ihrem Urteil zwei Fragen zum eigenen Tod. Anschließend setzen sie für eine mutmaßliche Prostituierte eine durchschnittliche Kaution von 455 Dollar fest. Die Kontrollgruppe, die diese Fragen nicht bekommen hat, setzt im Schnitt 50 Dollar fest. Das Experiment umfasste 22 Richter; mehrere große Wiederholungsversuche zu verwandten Befunden sind seither gescheitert.","kurz":"Der Unterschied passt zu einer Deutung: Der Gedanke an den eigenen Tod kann das Bedürfnis wecken, die eigene Weltanschauung zu verteidigen. Bei nur 22 Richtern und gescheiterten Wiederholungen verwandter Befunde bleibt das eine vorläufige Vermutung, keine gesicherte Tatsache.","prueffrage":"Wie viele Personen liegen den Zahlen zugrunde, und hat jemand das Experiment später mit anderen Teilnehmern wiederholt?","rueckmeldung":[{"option":1,"text":"Dass sich Urteile an einer genannten Zahl orientieren können, ist ein bekanntes Phänomen. Hier fehlt aber der Anlass: Die Fragen zum eigenen Tod enthielten keine Zahl, an der sich die Kaution hätte ausrichten können."},{"option":2,"text":"Ein Vorurteil gegen die Angeklagten könnte Strenge erklären. Beide Gruppen urteilten jedoch über denselben Fall, ein solches Vorurteil läge also bei beiden vor und erklärt nicht, warum nur eine so viel härter entschied."},{"option":3,"text":"Erschöpfte Menschen urteilen tatsächlich oft flüchtiger und härter. Zwei kurze Fragen sind aber kaum geeignet, jemanden so zu ermüden, dass sich daraus ein Unterschied von 455 zu 50 Dollar erklärte."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"literatur","kurz":"Rosenblatt, Greenberg, Solomon, Pyszczynski & Lyon (1989): Evidence for terror management theory I. Journal of Personality and Social Psychology 57(4), 681–690","oeffentlich":false},{"typ":"doi","kurz":"Klein, R. A. u. a. (2022): Many Labs 4: Failure to Replicate Mortality Salience Effect With and Without Original Author Involvement. Collabra: Psychology 8(1), 35271","oeffentlich":true,"doi":"10.1525/collabra.35271","abruf":"2026-10-12"},{"typ":"doi","kurz":"Treger, Benau & Timko (2023): Not so terrifying after all? PLOS ONE 18(5), e0285267","oeffentlich":true,"doi":"10.1371/journal.pone.0285267","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3c03f0e687172c82"}},{"id":"qx-h-006","clusterId":"H","werkstueckRef":"H.0.1","stufe":2,"question":"Welche Erklärung für seinen Sog zum Mythos passt am besten zu allem, was du über ihn weißt, und lässt sich gut prüfen?","scenario":"Ein Bekannter hat kurz nacheinander seinen Job verloren und eine schwere Krankheit durchgemacht. Seitdem erzählt er begeistert, er gehöre zu den „Erwachten“, die einen verborgenen Plan durchschauen und gegen ihn kämpfen. Eine Freundin vermutet, er habe einfach zu viel Zeit und zu wenig zu tun. Ein anderer meint: „Der war schon immer leichtgläubig.“ Du willst verstehen, was ihn wirklich anzieht.","options":["Der Mythos ersetzt weggebrochene Stützen: Er stiftet Sinn statt Chaos, gibt ihm als „Wissendem“ eine wichtige Rolle und verbindet ihn mit etwas Größerem.","Der Mythos füllt vor allem leere Zeit: Er bietet dem plötzlich unbeschäftigten Bekannten eine spannende Aufgabe, die Abwechslung und Beschäftigung liefert.","Der Mythos schließt eine Wissenslücke: Wer die Zusammenhänge hinter Krisen nicht kennt, greift zur einfachsten Erklärung, die ihm begegnet.","Der Mythos gibt einem Misstrauen gegen Institutionen Ausdruck, das sich über Jahre aufgebaut hat und nun ein passendes Weltbild gefunden hat."],"correctIndex":0,"explanation":"Die Erklärung muss zu dem passen, was der Mythos ihm bietet, und zu dem, was bei ihm gerade zusammengebrochen ist. Jobverlust und Krankheit sind typische Phasen existenzieller Unsicherheit, in denen das bisherige „Terror-Management-System“ (die Stützen, die Sinn und Selbstwert tragen) zusammenbricht. Der Mythos ersetzt gleich mehrere Stützen auf einmal: Er macht aus einer chaotischen, bedeutungslosen Welt eine geordnete, in der alles einen Plan hat (Sinn). Er macht aus einem Menschen, dem Dinge zustoßen, einen „Erwachten“ mit heldenhafter Rolle (Selbstwert). Und er lässt ihn für „die Wahrheit“ oder eine bessere Welt kämpfen, also für etwas, das größer ist als er selbst (symbolische Unsterblichkeit). Eine Einschränkung gehört dazu: Ob unbewusste Todesangst dahintersteckt, ist empirisch umstritten, denn große Wiederholungsstudien dazu sind gescheitert. Als Erklärung des Motivs „Sinn, Selbstwert, Zugehörigkeit zu etwas Größerem nach dem Zusammenbruch der bisherigen Stützen“ trägt die Überlegung aber auch ohne diese Zusatzannahme. Das ist eine Hypothese, die du im Gespräch prüfen kannst, kein Urteil über ihn. Leere Zeit kann ein Thema füllen, erklärt aber nicht, warum er sich als Wissender fühlt und für etwas kämpft. Eine Wissenslücke erklärt, warum eine einfache Erklärung gefällt, nicht aber den Zeitpunkt nach Jobverlust und Krankheit und seine Begeisterung. Ein über Jahre gewachsenes Misstrauen passt nicht zu einem Wandel, der erst mit diesen beiden Schlägen begann.","coreRule":"⚡ Frag bei einer Überzeugung: Was bietet sie, und was ist gerade weggebrochen? Wer Sinn, Rolle und Größeres zugleich verspricht, lockt am stärksten.","beleg":"Werkstück H.0.1 (Anwendung & Relevanz: Verschwörungsmythos, Anfälligkeit); Fn. gl-h-1 (Rosenblatt u. a. 1989; Transparenzhinweis zu Klein u. a. 2022, Many Labs 4)","status":"entwurf","kurz":"Nach Jobverlust und Krankheit fehlen ihm mehrere Stützen auf einmal. Der Mythos bietet Sinn, eine heldenhafte Rolle und Zugehörigkeit zu etwas Größerem. Eine Erklärung, die nur ein Teilstück trifft, lässt gerade den Zeitpunkt und die Begeisterung offen.","prueffrage":"Was erzählt er selbst, wenn er begeistert vom „Erwachtsein“ spricht, und was hat er seit Jobverlust und Krankheit verloren?","rueckmeldung":[{"option":1,"text":"Freie Zeit kann ein Thema durchaus füllen, und das liegt nach dem Jobverlust nahe. Sie erklärt aber nicht, warum er sich als Wissender fühlt und für etwas kämpft, und auch die Krankheit bliebe unberücksichtigt."},{"option":2,"text":"Wer Zusammenhänge nicht kennt, greift oft zur einfachen Erklärung. Warum aber gerade jetzt, nach Jobverlust und Krankheit, und woher seine Begeisterung als „Erwachter“ rührt, bleibt dabei offen."},{"option":3,"text":"Ein langes Misstrauen würde sein Weltbild plausibel machen. Der Wandel setzte laut Szenario aber erst mit den beiden Schlägen ein; die zeitliche Abfolge spricht daher eher gegen einen jahrelang gewachsenen Hintergrund."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Douglas, Sutton & Cichocka (2017): The Psychology of Conspiracy Theories. Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"},{"typ":"doi","kurz":"Treger, Benau & Timko (2023): Not so terrifying after all? PLOS ONE 18(5), e0285267","oeffentlich":true,"doi":"10.1371/journal.pone.0285267","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook (Ohnmacht, Bedrohung, Unsicherheit als Treiber)","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"4","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0b1c78d088422560"}},{"id":"qx-h-007","clusterId":"H","werkstueckRef":"H.0.1","stufe":3,"question":"Wie solltest du die Behauptung deiner Freundin am besten einschätzen?","scenario":"Eine Freundin sagt: „Das Richter-Experiment mit 455 statt 50 Dollar Kaution beweist doch, dass Todesangst Menschen härter urteilen lässt.“ Du weißt: Der Befund stammt aus einer Studie von 1989 mit 22 Richtern. Seither sind mehrere große Wiederholungsversuche zur Todeserinnerung gescheitert, und ein anderer klassischer Befund desselben Forschungsfelds ließ sich in einer großen Wiederholung unter keiner Bedingung bestätigen. Das Richter-Experiment selbst wurde bisher nicht groß wiederholt.","options":["Als Hinweis, aber nicht als Beweis: Die Stichprobe war klein, verwandte Befunde ließen sich nicht wiederholen.","Als solide, weil sie lange anerkannt war: Ein Befund, der Jahrzehnte im Fach galt, verdient im Allgemeinen Vertrauen.","Als aussagekräftig, weil der Unterschied groß ist: Das spricht trotz kleiner Stichprobe für einen echten Effekt.","Als stimmig, weil die Deutung einleuchtet: Passt eine Erklärung zur Theorie, wiegt das schwerer als die Stichprobengröße."],"correctIndex":0,"explanation":"Eine Studie mit nur 22 Richtern ist klein, ihr Ergebnis taugt deshalb nicht als Beweis. Dazu kommt, dass mehrere große Wiederholungsversuche zur Todeserinnerung gescheitert sind. In der großen Replikation „Many Labs 4“ (Klein u. a. 2022) ließ sich ein anderer klassischer Befund desselben Forschungsfelds unter keiner Bedingung bestätigen; das Richter-Experiment von 1989 selbst wurde dort nicht wiederholt. Es gilt heute nicht mehr als unangefochten gesichert. Ein gescheiterter Befund aus demselben Forschungsfeld ist ein Warnsignal, aber kein Gegenbeweis für diese eine Studie. Angemessen ist ein vorsichtiges Urteil: ein Hinweis, der geprüft werden müsste, weder ein Beweis noch einfach Unsinn. Dass ein Befund lange im Fach galt, sagt wenig über seine Belastbarkeit, wenn Wiederholungen im selben Feld misslingen. Ein großer Unterschied in einer kleinen Stichprobe ist eher ein Warnzeichen für Zufall als ein Beleg. Und dass eine Deutung einleuchtet, ersetzt keine Daten, die tragen.","coreRule":"⚡ Eine kleine Einzelstudie ist ein Hinweis, kein Beweis: Erst Wiederholungen entscheiden, und ein Warnsignal aus dem Umfeld ist noch keine Widerlegung.","beleg":"Werkstück H.0.1 (Der Richter und das Kruzifix); Fn. gl-h-1 (Rosenblatt u. a. 1989, JPSP 57(4), S. 681–690, Exp. 1 S. 682; Klein u. a. 2022, Collabra 8(1))","status":"entwurf","kurz":"22 Richter sind eine kleine Stichprobe, und große Wiederholungen im selben Forschungsfeld sind gescheitert. Das Ergebnis ist deshalb ein Hinweis, der geprüft werden müsste, kein Beweis. Der Fehler wäre, ihm wegen seines Alters oder seiner Plausibilität mehr zuzutrauen.","prueffrage":"Wie oft und in welcher Größe wurde dieser Befund seit 1989 unabhängig nachgeprüft?","rueckmeldung":[{"option":1,"text":"Dass ein Befund lange im Fach galt, wirkt wie eine bestandene Probe. Es sagt aber wenig über seine Belastbarkeit, wenn Wiederholungen im selben Feld misslingen; auch langjährig Anerkanntes kann sich später als wackelig erweisen."},{"option":2,"text":"Der Unterschied von 455 zu 50 Dollar ist tatsächlich groß. In einer kleinen Stichprobe von 22 Personen schlagen Zufallsschwankungen aber stark aus, ein großer Unterschied dort ist eher ein Warnzeichen als ein Beleg für einen echten Effekt."},{"option":3,"text":"Eine Deutung, die einleuchtet, fühlt sich überzeugend an. Plausibilität ersetzt aber keine Daten, die tragen: Eine passende Theorie macht eine kleine Stichprobe nicht aussagekräftiger."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Klein, R. A. u. a. (2022): Many Labs 4: Failure to Replicate Mortality Salience Effect With and Without Original Author Involvement. Collabra: Psychology 8(1), 35271","oeffentlich":true,"doi":"10.1525/collabra.35271","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Rosenblatt, Greenberg, Solomon, Pyszczynski & Lyon (1989): Evidence for terror management theory I. Journal of Personality and Social Psychology 57(4), 681–690","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ffd2649caa3b6855"}},{"id":"qx-h-008","clusterId":"H","werkstueckRef":"H.0.1","stufe":3,"question":"Was ist an dieser Schlussfolgerung fehlerhaft?","options":["Er schließt vom Zweck einer Überzeugung auf ihren Wert; dass sie vor Angst schützt, macht sie nicht schädlich, das zeigt sich erst an ihren Folgen.","Er stützt sich nur auf die Autorität einer Theorie; dass Fachleute sie vertreten, macht eine Schlussfolgerung noch nicht richtig.","Er hält eine Annahme für richtig, weil sie bisher nicht widerlegt wurde; fehlende Gegenbeweise machen eine Aussage aber noch nicht wahr.","Er stellt die Theorie verzerrt dar, um sie leichter angreifen zu können; in Wahrheit behauptet sie etwas ganz anderes, als er ihr zuschreibt."],"correctIndex":0,"explanation":"Der Fehlschluss springt vom Ursprung oder Zweck einer Überzeugung auf ihren Wert. Dass etwas ein Bedürfnis erfüllt, sagt weder, dass es wahr ist, noch, dass es schädlich ist. Folgt man der Theorie, kann dieselbe Quelle Kathedralen, Forschung und Familiengründungen antreiben, aber auch Hass. Kritisch wird es dort, wo die Verteidigung der eigenen Weltanschauung wichtiger wird als Realität oder Menschlichkeit, etwa wenn man Andersdenkende verletzt oder Fakten leugnet. Ob eine Überzeugung ungesund ist, zeigt sich also an ihren Folgen, nicht an ihrer Herkunft. Die bewusste Selbstprüfung, ob die Wut vom Argument oder von der Bedrohung des eigenen Glaubenssatzes kommt, hilft, diese Grenze rechtzeitig zu bemerken. Ein Autoritätsargument liegt nicht vor, denn niemand beruft sich auf Fachleute. Dass etwas nicht widerlegt sei, wird nicht als Begründung angeführt. Und die Theorie wird zutreffend wiedergegeben, der Fehler beginnt erst beim Schluss daraus.","coreRule":"⚡ Von der Herkunft einer Überzeugung auf ihren Wert zu schließen, ist ein Fehlschluss. Prüfe, was sie im Verhalten bewirkt.","beleg":"Werkstück H.0.1 (Das Adaptive Talent; Der Kipppunkt; Das Anti-Denkmuster)","status":"entwurf","scenario":"In einer Diskussion sagt jemand: „Menschen schützen sich mit festen Überzeugungen vor der Angst vor dem Tod. Also ist jede feste Überzeugung ungesund, und wer sich wie eine Pflegerin, ein Patriot oder eine Gläubige auf einen Sinn stützt, macht sich etwas vor.“","kurz":"Dass eine Überzeugung ein Bedürfnis erfüllt, sagt weder, dass sie wahr ist, noch, dass sie schadet. Der Fehler liegt im Sprung von ihrem Zweck auf ihren Wert; ob sie ungesund ist, zeigt sich erst an ihren Folgen.","prueffrage":"Was nennt der Sprecher als Grund, und was behauptet er am Ende über die Überzeugungen?","rueckmeldung":[{"option":1,"text":"Eine Autorität wird hier gar nicht angeführt: Niemand sagt „Fachleute sehen das so“, der Sprecher nennt eine Theorie und zieht selbst einen Schluss daraus. Der Fehler steckt in diesem Schluss, nicht in einem Verweis auf Experten."},{"option":2,"text":"Der Satz stützt sich nicht darauf, dass etwas bisher nicht widerlegt wurde. Er behauptet einen Zusammenhang und zieht daraus eine Wertung. Dass fehlende Gegenbeweise nichts beweisen, stimmt allgemein, ist hier aber nicht der Punkt."},{"option":3,"text":"Eine Verzerrung läge vor, wenn die Theorie falsch wiedergegeben würde. Sie wird aber zutreffend dargestellt: Feste Überzeugungen können vor Todesangst schützen. Der Fehler beginnt erst bei dem, was der Sprecher daraus folgert."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Eintrag „Genetic Fallacy“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f38a595baf1f41b0"}},{"id":"qx-h-009","clusterId":"H","werkstueckRef":"H.1.1","stufe":1,"question":"Welche Haltung hilft Karim am ehesten, mit dieser Kritik produktiv umzugehen?","options":["Er sollte standhaft bleiben und den Plan verteidigen, denn wer bei der ersten Kritik nachgibt, wirkt auf andere unglaubwürdig.","Er sollte klären, wie die übrigen Mitbewohner den Plan sehen, und sich der Mehrheit anschließen, damit die Entscheidung gerecht ausfällt.","Er sollte das Thema für diese Woche ruhen lassen und erst später auf Lenas Einwand eingehen, damit sich die Stimmung beruhigt.","Er sollte sich klarmachen, dass der Plan nur eine Hypothese ist, die scheitern darf, ohne dass sein eigener Wert daran hängt."],"correctIndex":3,"explanation":"Karims Gedanke „Wenn mein Plan nichts taugt, tauge ich nichts“ verschmilzt Person und Idee. Genau dadurch wird Kritik als Angriff auf ihn selbst erlebt, und das Ziel kippt von „den besten Plan finden“ zu „mich verteidigen“. Hilfreich ist der mentale Abstand: Der Plan ist etwas, das Karim hat, nicht etwas, das er ist. Dann kann er Lenas Einwand ernsthaft prüfen, vielleicht nachbessern oder verwerfen, ohne sich selbst infrage zu stellen. Karim darf sich dabei ärgern, entscheidend ist, dass der Ärger nicht über die Prüfung des Plans entscheidet. Standhaft zu bleiben hilft bei unberechtigter Kritik, hier wäre es aber nur Selbstverteidigung, und Lenas Einwand bliebe ungeprüft. Die Mitbewohner zu befragen ist als Entscheidungsweg legitim, löst aber nicht Karims Gleichsetzung von Plan und Person. Eine Pause kann den Ärger dämpfen, ändert aber nichts daran, dass er Kritik am Plan als Urteil über sich erlebt.","coreRule":"⚡ Du hast deine Idee, du bist nicht deine Idee.","beleg":"Werkstück H.1.1 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"Karim hat vorgeschlagen, den Hausflur der Wohngemeinschaft jede Woche im Wechsel zu putzen. Auf der Hausversammlung nimmt Lena den Plan auseinander: Bei drei Mitbewohnern in Schichtarbeit sei er unrealistisch. Karim merkt, wie ihm die Hitze ins Gesicht steigt, und denkt: „Wenn mein Plan nichts taugt, tauge ich nichts.“","kurz":"Karim darf sich ärgern, entscheidend ist aber der Abstand: Der Plan ist etwas, das er hat, nicht etwas, das er ist. Erst dann kann er Lenas Einwand prüfen, statt sich zu verteidigen, weil er Kritik am Plan als Urteil über sich erlebt.","prueffrage":"Was genau wirft Lena dem Plan vor, und lässt sich das an den Schichtzeiten der drei Mitbewohner nachprüfen?","rueckmeldung":[{"option":0,"text":"Standhaft zu bleiben ist bei unberechtigter Kritik sinnvoll. Hier wäre es aber vor allem Selbstverteidigung, und Lenas Einwand mit der Schichtarbeit bliebe ungeprüft. Ob der Plan trägt, würde nicht mehr zählen."},{"option":1,"text":"Die anderen nach ihrer Sicht zu fragen, ist als Entscheidungsweg durchaus legitim. Karims Problem liegt aber früher: Er setzt Plan und Person gleich. Das ändert sich nicht dadurch, dass er sich einer Mehrheit anschließt."},{"option":2,"text":"Ein Aufschub kann den Ärger dämpfen, das stimmt. Der Gedanke „Wenn mein Plan nichts taugt, tauge ich nichts“ bleibt aber bestehen, und Karim würde Lenas Einwand später genauso als Angriff auf sich erleben."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Hayes, Levin, Plumb-Vilardaga, Villatte & Pistorello (2013): Acceptance and Commitment Therapy and Contextual Behavioral Science. Behavior Therapy 44(2), 180–198 (PMC-Fassung)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3635495/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d377178b82eb2ce0"}},{"id":"qx-h-010","clusterId":"H","werkstueckRef":"H.1.1","stufe":2,"question":"Wie ist dieses Signal am sinnvollsten zu deuten?","scenario":"Du merkst mitten in einer Diskussion über Politik, wie dir heiß wird und du nur noch deine Seite verteidigen willst, statt zuzuhören.","options":["Als Zeichen besonders gründlichen Denkens: Starke Gefühle zeigen, dass dein System 2 gerade hart an der Wahrheit arbeitet und dabei nichts übersieht.","Als Alarmsignal: Deine Identität verschmilzt gerade mit deiner Idee, das schnelle, automatische Denken übernimmt, und es geht dir weniger um Wahrheit als um Selbstverteidigung.","Als Hinweis darauf, dass dein Gegenüber im Kern recht hat: Wut entsteht vor allem dann, wenn man etwas Wahres und Unbequemes über die eigene Position hört.","Als Zeichen, dass du das Thema nie wieder diskutieren solltest: Starke Überzeugung ist immer ein Merkmal von Dogmatik, der man aus dem Weg gehen muss."],"correctIndex":1,"explanation":"Wenn eine Kritik an der Idee wie ein Angriff auf die eigene Person wirkt, springt das automatische, emotionale Verteidigungssystem an. Die Logik schaltet sich dabei nicht ab, sie wechselt die Seite: Sie dient nun dazu, die eigene Identität zu schützen, nicht dazu, die Wahrheit zu finden. Dazu passt ein viel zitiertes Experiment: Bei einer Hautcreme entschied das Rechenkönnen über die richtige Antwort auf eine Vierfeldertafel, beim Waffenverbot spaltete sich die Auswertung entlang der Weltanschauung. Spätere Wiederholungen bestätigten die weltanschauliche Färbung nur teilweise, die Verstärkung durch Rechenkönnen fanden sie nicht. Hitze und Abwehr sagen also etwas über deinen inneren Zustand, nicht über die Wahrheit der Sache. Ein starkes Gefühl beweist weder gründliches Denken noch, dass das Gegenüber recht hat. Und starke Überzeugung ist an sich noch kein Grund, ein Thema zu meiden. Hilfreich ist Abstand zur eigenen Idee: Sie ist etwas, das du hast, nicht etwas, das du bist.","coreRule":"⚡ Wirst du wütend und defensiv, verteidigst du vermutlich gerade dich und nicht die Wahrheit.","beleg":"Werkstück H.1.1 (Anwendung & Relevanz: ‚In jeder hitzigen Debatte‘; Kontext & Tiefe); Fn. gl-h-motiviert (Kahan u. a. 2017, zur motivierten Verarbeitung bei politischen Themen; Wiederholungen: Persson u. a. 2021, Stagnaro u. a. 2023)","status":"entwurf","kurz":"Wenn Kritik an der Idee wie ein Angriff auf dich wirkt, übernimmt das automatische Verteidigungssystem, und die Logik dient dann dem Schutz deiner Identität, nicht der Wahrheitssuche. Wer Hitze für Gründlichkeit hält, übersieht genau das.","prueffrage":"Was weißt du über die Sache selbst jetzt mehr als vor dem Moment, in dem dir heiß wurde?","rueckmeldung":[{"option":0,"text":"Ein starkes Gefühl wirkt wie ein Beweis dafür, dass dir die Sache ernst ist und du sie durchdenkst. Hitze und Abwehr sagen aber etwas über deinen inneren Zustand, nicht über gründliches Denken: Eher verteidigst du gerade dich selbst."},{"option":2,"text":"Dass Unbequemes Abwehr auslösen kann, ist denkbar. Aus der Wut lässt sich aber nicht ablesen, ob das Gegenüber recht hat: Sie verrät etwas über deinen inneren Zustand, nicht über die Wahrheit der Sache."},{"option":3,"text":"Auf starke Überzeugung zu achten ist sinnvoll, aber sie gleich als Dogmatik zu verwerfen, geht zu weit. Überzeugung allein ist kein Grund, ein Thema zu meiden; hilfreich ist Abstand zur eigenen Idee, nicht Ausweichen."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Stagnaro, Tappin & Rand (2023): No association between numerical ability and politically motivated reasoning in a large US probability sample. PNAS 120(32), e2301491120","oeffentlich":true,"doi":"10.1073/pnas.2301491120","abruf":"2026-10-12"},{"typ":"doi","kurz":"Persson, Andersson, Koppel, Västfjäll & Tinghög (2021): A preregistered replication of motivated numeracy. Cognition 214, 104768","oeffentlich":true,"doi":"10.1016/j.cognition.2021.104768","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kahan, Peters, Dawson & Slovic (2017): Motivated numeracy and enlightened self-government. Behavioural Public Policy 1(1), 54–86","oeffentlich":false,"doi":"10.1017/bpp.2016.2","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d59107ac6cfe5274"}},{"id":"qx-h-011","clusterId":"H","werkstueckRef":"H.1.1","stufe":4,"question":"Ein Experiment fand: Bei einem Waffenverbot spaltete sich die Auswertung einer Vierfeldertafel politisch, bei Rechenstarken sogar stärker, bei einer neutralen Hautcreme-Aufgabe dagegen nicht. Eine große vorregistrierte Wiederholung mit 3.154 Teilnehmern fand die weltanschauliche Färbung teilweise wieder, die Verstärkung durch Rechenkönnen aber nicht. Eine Forscherin will diesen Befund als Beleg dafür nutzen, dass die Logik die Seite wechselt, wenn die Identität bedroht ist. Wie belastbar ist der Befund „Rechenkönnen verstärkt die weltanschauliche Färbung“?","options":["Die weltanschauliche Färbung beim politischen Thema ist teilweise bestätigt, dass Rechenkönnen sie verstärkt, ist es nicht; der Befund trägt die Aussage nur eingeschränkt.","Die Wiederholung hat sowohl die weltanschauliche Färbung als auch deren Verstärkung durch Rechenkönnen bestätigt; der Befund trägt die Aussage vollständig.","Die Wiederholung hat gezeigt, dass die Weltanschauung bei der Auswertung gar keine Rolle spielt; der Befund trägt die Aussage nicht.","Die Wiederholung hat gezeigt, dass Rechenschwache sich stärker von ihrer Weltanschauung leiten lassen; der Befund trägt die Aussage nur für diese Gruppe."],"correctIndex":0,"explanation":"Beim Hautcreme-Beispiel schnitten die Rechenstärksten deutlich besser ab. Beim Waffenverbot wurden die Antworten politisch gespalten, bei den Rechenstärksten sogar stärker. Die große vorregistrierte Wiederholung (Persson u. a. 2021, 3.154 Teilnehmer) fand die weltanschauliche Färbung zum Teil wieder, die Verstärkung durch Rechenkönnen aber nicht. Eine zweite vorregistrierte Wiederholung mit einer repräsentativen US-Stichprobe (Stagnaro u. a. 2023, n = 2.355) fand ebenfalls keine Verstärkung durch Rechenkönnen, wohl aber um 9,3 Prozentpunkte häufiger richtige Antworten bei einem zur eigenen Politik passenden Ergebnis. Die Originalstudie ließ sich also nur teilweise wiederholen, und ein nur teilweise bestätigter Befund darf nicht als gesichert gelten. Die Kernaussage „Weltanschauung färbt die Datenauswertung“ ist besser gestützt als der Zusatz „Rechenkönnen verstärkt das“. Als Beleg für „Logik als Anwalt der Identität“ taugt er deshalb nur mit diesem Vorbehalt.","coreRule":"⚡ Ein Befund ist nur so belastbar wie seine Wiederholung: Was sich nur teilweise bestätigt, darf nur teilweise behauptet werden.","beleg":"Werkstück H.1.1 (Kontext & Tiefe); Fn. gl-h-motiviert (Kahan u. a. 2017, Behavioural Public Policy 1(1), S. 54–86; Persson u. a. 2021, Cognition 214, Art. 104768, S. 1 und 6)","status":"entwurf","scenario":"","kurz":"Wiedergefunden wurde nur die weltanschauliche Färbung, und selbst die nur zum Teil; die Verstärkung durch Rechenkönnen blieb in der großen Wiederholung aus, ebenso in einer weiteren. Ein halb bestätigter Befund taugt daher nur eingeschränkt als Beleg.","prueffrage":"Was müsste eine Wiederholung zeigen, damit man von einer vollständigen Bestätigung sprechen kann?","rueckmeldung":[{"option":1,"text":"Eine Wiederholung mit über dreitausend Teilnehmern klingt nach einer vollen Bestätigung. Sie fand aber nur die Färbung zum Teil wieder, die Verstärkung durch Rechenkönnen dagegen nicht. „Vollständig“ trägt hier nicht."},{"option":2,"text":"Dass die Verstärkung ausblieb und der Befund die Aussage nicht voll trägt, stimmt. Die weltanschauliche Färbung fand die Wiederholung aber zum Teil wieder; dass die Weltanschauung gar keine Rolle spielt, geht daher zu weit."},{"option":3,"text":"Wenn Rechenkönnen die Färbung nicht verstärkt, liegt die Umkehrung nahe. Gefunden wurde aber nur, dass die Verstärkung ausblieb, nicht, dass Rechenschwache sich stärker von ihrer Weltanschauung leiten lassen; das wäre hinzugedichtet."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Stagnaro, Tappin & Rand (2023): No association between numerical ability and politically motivated reasoning in a large US probability sample. PNAS 120(32), e2301491120","oeffentlich":true,"doi":"10.1073/pnas.2301491120","abruf":"2026-10-12"},{"typ":"doi","kurz":"Persson, Andersson, Koppel, Västfjäll & Tinghög (2021): A preregistered replication of motivated numeracy. Cognition 214, 104768","oeffentlich":true,"doi":"10.1016/j.cognition.2021.104768","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kahan, Peters, Dawson & Slovic (2017): Motivated numeracy and enlightened self-government. Behavioural Public Policy 1(1), 54–86","oeffentlich":false,"doi":"10.1017/bpp.2016.2","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"4885a2f82785cf11"}},{"id":"qx-h-012","clusterId":"H","werkstueckRef":"H.1.1","stufe":3,"question":"Wie beurteilst du die Gleichsetzung deines Freundes?","scenario":"Ein Freund aus der Psychologie sagt: „Kognitive Entkopplung kenne ich von Keith Stanovich, das ist genau das, was du meinst, wenn du sagst: Meine Idee ist etwas, das ich habe, nicht etwas, das ich bin.“ Du erinnerst dich, dass Stanovich unter „cognitive decoupling“ die Fähigkeit versteht, probeweise Annahmen von der Vorstellung der wirklichen Welt getrennt zu halten und die schnelle, automatische Antwort zu übersteuern.","options":["Sie ist richtig, weil beide Begriffe dasselbe meinen: das Lösen der eigenen Identität von Überzeugungen.","Sie ist halb richtig, weil beide Begriffe Gefühl und Verstand trennen und nur die Gruppenidentität hinzukommt.","Sie ist falsch, weil derselbe Name zwei verschiedene Fähigkeiten meint: Annahmen trennen versus Selbstwert trennen.","Sie ist falsch, weil Stanovichs Begriff aus der Akzeptanz- und Commitment-Therapie stammt und dort unverändert gilt."],"correctIndex":2,"explanation":"Ein gleicher Name sagt noch nichts über eine gleiche Sache. Bei Stanovich bedeutet „cognitive decoupling“, probeweise Annahmen von der Vorstellung der wirklichen Welt getrennt zu halten und die schnelle, automatische Antwort zu übersteuern. Das ist eine Denkfähigkeit beim probeweisen Durchspielen von Annahmen. Selbstwert und Identität von den eigenen Überzeugungen zu lösen, ist etwas anderes: Es betrifft das Verhältnis zu den eigenen Ideen, nicht das Durchspielen von Annahmen. Näher kommen dem zwei Begriffe aus der Akzeptanz- und Commitment-Therapie, die „kognitive Defusion“ (Gedanken als Gedanken bemerken, statt sie wörtlich zu nehmen) und das „Selbst als Kontext“ (die Bindung an die eigene Selbsterzählung lockern). Prüfe deshalb, was mit dem Begriff tatsächlich gemeint ist.","coreRule":"⚡ Prüfe bei Fachbegriffen, ob derselbe Name dieselbe Bedeutung trägt.","beleg":"Werkstück H.1.1; Fn. gl-h-entkopplung (nach Woods 2012, Informal Logic 32(3), S. 375 f., zu Stanovich: Rationality and the Reflective Mind, 2011); Anmerkung anm-gl-h-entkopplung","status":"entwurf","kurz":"Gleiche Namen sagen noch nichts über gleiche Sachen. Stanovich meint das probeweise Durchspielen von Annahmen, getrennt von der Vorstellung der wirklichen Welt. Selbstwert von Überzeugungen zu lösen, betrifft dagegen das Verhältnis zu den eigenen Ideen.","prueffrage":"Was müsste in Stanovichs Beschreibung stehen, damit die Gleichsetzung deines Freundes stimmt?","rueckmeldung":[{"option":0,"text":"Dass beide Begriffe mit Abstand zu Gedanken zu tun haben, lässt sie ähnlich wirken. Stanovich meint aber das probeweise Durchspielen von Annahmen und das Übersteuern der schnellen Antwort, nicht die Lösung der Identität von Überzeugungen."},{"option":1,"text":"Dass die schnelle, automatische Antwort übersteuert wird, klingt nach einer Trennung von Gefühl und Verstand. Stanovichs Begriff meint aber das Trennen probeweiser Annahmen von der wirklichen Welt, und eine Gruppenidentität kommt darin gar nicht vor."},{"option":3,"text":"Die Akzeptanz- und Commitment-Therapie ist ein guter Anhaltspunkt, nur für den falschen Begriff: Stanovichs „cognitive decoupling“ stammt aus der Denkforschung. Näher am Gemeinten sind „kognitive Defusion“ und „Selbst als Kontext“ aus der Therapie."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Woods, C. (2012): Rezension zu Stanovich, Rationality and the Reflective Mind. Informal Logic 32(3), 373–380","oeffentlich":true,"doi":"10.22329/il.v32i3.3721","abruf":"2026-10-12"},{"typ":"url","kurz":"Hayes, Levin, Plumb-Vilardaga, Villatte & Pistorello (2013): Acceptance and Commitment Therapy and Contextual Behavioral Science. Behavior Therapy 44(2) (PMC-Fassung)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3635495/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Evans, J. St. B. T. & Stanovich, K. E. (2013): Dual-Process Theories of Higher Cognition: Advancing the Debate. Perspectives on Psychological Science 8(3), 223–241","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f173dddc04c7a9c0"}},{"id":"qx-h-013","clusterId":"H","werkstueckRef":"H.1.2","stufe":1,"question":"Jemand beschreibt seinen Alltag so: „Ich korrigiere jeden falschen Kommentar, den ich sehe, und diskutiere mit jedem, der Unsinn verbreitet. Inzwischen bin ich nach den Diskussionen ständig erschöpft und wütend, und für das Gespräch mit meinem Vater, der gerade eine ärztlich empfohlene Behandlung ablehnen will, habe ich kaum noch Kraft.“ Welche Schlussfolgerung ist am besten begründet?","options":["Er sollte seine Korrekturen freundlicher formulieren, weil ein sachlicher Ton die Chance erhöht, dass andere Argumente annehmen.","Er sollte seine begrenzte Energie nach Dringlichkeit einteilen, weil zuerst das Gespräch mit seinem Vater zählt, wo ein echter Schaden droht.","Er sollte vor jeder Korrektur die eigene Quelle gegenprüfen, weil auch gut gemeinte Richtigstellungen selbst fehlerhaft sein können.","Er sollte seine Wut als Hinweis auf eigene Voreingenommenheit prüfen, weil starke Gefühle oft zeigen, dass man nicht neutral urteilt."],"correctIndex":1,"explanation":"Mentale und emotionale Energie ist begrenzt. Wer jeden Irrtum sofort bekämpft, hat am Ende keine Kraft mehr für die Situation, in der Nichtstun echten Schaden anrichtet, hier die drohende Ablehnung einer ärztlich empfohlenen Behandlung. Sinnvoll ist eine Triage: Wo unmittelbarer Schaden droht, lohnt sich der volle Einsatz. Wo ein Gespräch noch offen und konstruktiv wirkt, kann man vorsichtig Energie investieren. Bei aussichtslosen Streitereien spart man sie. Die anderen Gedanken sind für sich vernünftig, lösen aber das geschilderte Problem nicht: Ein freundlicher Ton erhöht die Chance auf Gehör, ändert aber nichts daran, dass die Kraft schon aufgebraucht ist. Die eigene Quelle zu prüfen ist guter Stil, doch das Problem sind nicht fehlerhafte Korrekturen, sondern Überlastung. Die Wut als Signal zu lesen kann aufschlussreich sein, verteilt die begrenzte Kraft aber nicht neu.","coreRule":"⚡ Energie ist begrenzt: erst einteilen, dann kämpfen.","quote":"","quoteLabel":"","beleg":"Werkstück H.1.2 (Die Geschichte; Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Kraft ist begrenzt, und wer jeden Irrtum bekämpft, hat sie dort nicht mehr, wo echter Schaden droht, hier beim Vater und der abgelehnten Behandlung. Besser ist eine Triage: voller Einsatz, wo Schaden droht, sonst sparen.","prueffrage":"Was geschieht in den kommenden Wochen, wenn er so weitermacht wie bisher?","rueckmeldung":[{"option":0,"text":"Ein freundlicher Ton erhöht oft die Chance, gehört zu werden. Die Kraft, die nach den vielen Diskussionen fehlt, bringt er aber nicht zurück, und genau sie ist hier das Problem."},{"option":2,"text":"Die eigene Quelle zu prüfen ist guter Stil, denn auch gut gemeinte Korrekturen können fehlerhaft sein. Von falschen Korrekturen ist hier aber keine Rede; erschöpft ist der Mann von der schieren Menge an Diskussionen."},{"option":3,"text":"Starke Gefühle können tatsächlich auf Voreingenommenheit hindeuten, und das zu prüfen kann aufschlussreich sein. Die Wut erklärt hier aber nur die Erschöpfung und verteilt die knappe Kraft nicht neu."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"957909eb663b3556"}},{"id":"qx-h-014","clusterId":"H","werkstueckRef":"H.1.2","stufe":2,"question":"In welcher dieser Situationen ist es am besten begründet, deine Energie voll einzusetzen, auch wenn es anstrengend wird?","scenario":"Du hast nur begrenzt Kraft für Auseinandersetzungen und musst sie einteilen. Drei Situationen stehen an: (1) Ein anonymer Kommentator unter einem Video behauptet Unsinn und beschimpft jeden, der widerspricht. (2) Ein Kollege fragt dich ehrlich, ob an einer Gesundheitsmeldung etwas dran ist, und wirkt unsicher. (3) Dein Onkel will eine ärztlich empfohlene, lebensrettende Behandlung absagen und stattdessen auf eine unbewiesene Methode setzen.","options":["Beim Kommentator, weil eine öffentliche Falschbehauptung viele erreicht und die größte Reichweite hat.","Beim Kollegen, weil ein ehrlich Fragender offen ist und sich der Aufwand dort am meisten auszahlt.","Beim Onkel, weil hier Nichtstun direkten Schaden anrichtet und sich der Einsatz daher lohnt.","In allen dreien gleich, weil nur Beständigkeit glaubwürdig wirkt und Ausnahmen beliebig erscheinen."],"correctIndex":2,"explanation":"Wer seine Kräfte einteilt, fragt: Wo richtet Nichtstun direkten, unmittelbaren Schaden an? Beim Onkel will ein naher Angehöriger eine lebensrettende Behandlung zugunsten von Pseudomedizin ablehnen. Hier schadet Untätigkeit direkt, und das rechtfertigt vollen Einsatz, auch wenn er anstrengt. Die anderen Gedanken klingen sinnvoll, passen aber nicht: Reichweite ist hier kein Maßstab, denn der anonyme Kommentator beschimpft jeden, der widerspricht, und hat an einem Austausch kein Interesse, wer ihm antwortet, schüttet Energie in ein Fass ohne Boden. Beim Kollegen scheint ein konstruktiver Dialog möglich, dort kann ein vorsichtiger, strategischer Einsatz sinnvoll sein, aber ihm droht durch eine Gesundheitsmeldung kein Schaden, der vollen Einsatz verlangt. Beständigkeit wirkt zwar verlässlich, doch wer an allen Fronten gleich kämpft, verbraucht seine Kraft an Kleinem und fehlt, wenn es wirklich darauf ankommt.","coreRule":"⚡ Wo Nichtstun unmittelbaren Schaden anrichtet, lohnt der volle Einsatz.","beleg":"Werkstück H.1.2 (Kontext & Tiefe: Triage, Kategorie 1 „Die Schlachten, die man kämpfen muss“; Geschichte vom Feuerwehrmann)","status":"entwurf","kurz":"Wo Nichtstun direkten Schaden anrichtet, lohnt voller Einsatz: beim Onkel, der eine lebensrettende Behandlung abbrechen will. Reichweite, Offenheit oder Gleichbehandlung wirken sinnvoll, sagen aber nichts darüber, wo es wirklich darauf ankommt.","prueffrage":"Was steht in jeder der drei Situationen konkret auf dem Spiel, und für wen?","rueckmeldung":[{"option":0,"text":"Viele Leser sprechen für den Einsatz, nur ist Reichweite hier nicht das Maß. Der Kommentator beschimpft jeden, der widerspricht, und will keinen Austausch; wer ihm antwortet, verbraucht Kraft ohne Wirkung."},{"option":1,"text":"Beim Kollegen ist tatsächlich ein offenes Gespräch möglich, und dort kann ein vorsichtiger, gezielter Einsatz sinnvoll sein. Doch ihm droht durch die Gesundheitsmeldung kein Schaden, der vollen Einsatz verlangt."},{"option":3,"text":"Beständigkeit wirkt verlässlich, aber gleicher Aufwand überall verbraucht die begrenzte Kraft an Kleinem und fehlt dort, wo es um viel geht. Nach Schwere zu gewichten ist keine Beliebigkeit, sondern ein begründeter Maßstab."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook, Abschnitt „How to talk to a conspiracy theorist“","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"91c156d8de0b0109"}},{"id":"qx-h-015","clusterId":"H","werkstueckRef":"H.1.2","stufe":2,"question":"Welches Ziel für den nächsten Besuch ist vernünftig, und warum?","scenario":"Dein Vater hat sich in einen Mythos vertieft. Zwei längere Gespräche endeten im Streit, ohne dass er sich bewegt hat. Beim nächsten Besuch überlegst du, ob du wieder diskutierst.","options":["Ihm zu zeigen, wie viele Fachleute den Mythos ablehnen, damit er die Übermacht der Belege erkennt.","Die Beziehung zu halten und das Thema diesmal ruhen zu lassen, um das Vertrauen nicht zu gefährden.","Dich vorab über den Mythos zu informieren, um ihn beim Besuch lückenlos widerlegen zu können.","Den Mythos vor anderen richtigzustellen, um sie davor zu bewahren, auf ihn hereinzufallen."],"correctIndex":1,"explanation":"Maßstab ist, was im Familiengespräch wirklich zählt. Das Ziel ist oft nicht, die Person in einer einzigen Diskussion zu überzeugen, sondern die Beziehung zu erhalten und ein langfristiger, vertrauenswürdiger Ansprechpartner zu bleiben. Dazu gehört zu wissen, wann man ein Thema ruhen lassen muss, um die emotionale Verbindung nicht zu zerstören. Die anderen Ziele klingen für sich brauchbar, passen aber nicht: Weitere Belege oder Fachmeinungen vorzulegen setzt fort, was in zwei Gesprächen schon nichts bewegt hat. Bessere Vorbereitung hilft, wenn Wissen fehlt, ändert aber am Streitmuster zwischen euch wenig. Andere vor einem Mythos zu schützen ist ein gutes Ziel, wenn Dritte betroffen sind, hier geht es aber nur um deinen Vater.","coreRule":"⚡ In der Familie zählt zuerst die Verbindung, nicht der Sieg im Gespräch.","beleg":"Werkstück H.1.2 (Anwendung & Relevanz: ‚Bei Familiengesprächen („Mann über Bord“)‘)","status":"entwurf","kurz":"Nach zwei ergebnislosen Gesprächen zählt weniger, ihn zu überzeugen, als die Beziehung zu halten und ein vertrauenswürdiger Ansprechpartner zu bleiben. Der Denkfehler: Ruhenlassen mit Aufgeben zu verwechseln.","prueffrage":"Was haben die beiden langen Gespräche an der Meinung deines Vaters bewirkt, und wie endeten sie?","rueckmeldung":[{"option":0,"text":"Viele Fachleute sind ein starkes Indiz, deshalb klingt das Vorlegen überzeugend. Zwei Gespräche haben aber nichts bewegt, und noch mehr Belege setzen genau dieses Muster fort, statt es zu durchbrechen."},{"option":2,"text":"Gute Vorbereitung ist sinnvoll, wenn Wissen fehlt. Hier liegt das Problem aber im Streitmuster, und ein lückenloses Widerlegen will weiter gewinnen, statt die Beziehung zu schützen."},{"option":3,"text":"Andere vor einem Mythos zu schützen ist ein gutes Ziel, sobald Dritte betroffen sind. In dieser Lage geht es aber allein um deinen Vater, und das Ziel passt nicht zur Situation."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook, Abschnitt „How to talk to a conspiracy theorist“","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"45ae62d123b240e2"}},{"id":"qx-h-016","clusterId":"H","werkstueckRef":"H.1.2","stufe":3,"question":"Was ist hier die klügste Schlussfolgerung, und warum?","scenario":"Du diskutierst seit Wochen regelmäßig online mit Leuten über Verschwörungsmythen. Du merkst: Nach den Diskussionen bist du oft erschöpft, wütend und hoffnungslos, deine Antworten werden zynischer und aggressiver, und andere Dinge in deinem Leben kommen zu kurz. Überzeugt hast du bisher niemanden.","options":["Die Wut ist oft ein Hinweis auf eigene Vorurteile. Du solltest prüfen, ob in den Mythen ein wahrer Kern steckt, und deine Antworten daran ausrichten.","Unbelegte Gegenbehauptungen stärken Mythen eher. Du solltest vor jeder Antwort deine eigene Quelle prüfen und nur belegte Aussagen schreiben.","Zahlen überzeugen selten. Du solltest persönliche Geschichten erzählen, weil Menschen auf Erlebnisse stärker reagieren als auf Fakten.","Deine Kraft ist begrenzt und wird gerade verbraucht. Du solltest neu einteilen, welche Debatten sich lohnen, und aus den übrigen aussteigen."],"correctIndex":3,"explanation":"Erschöpfung, Wut, Hoffnungslosigkeit, wachsender Zynismus und vernachlässigte andere Lebensbereiche sind typische Warnzeichen für Überlastung. Mentale und emotionale Energie ist begrenzt, und wer an jeder Front kämpft, brennt aus und hat dann für die wirklich wichtigen Auseinandersetzungen keine Kraft mehr. Vernünftig ist eine Triage: Muss ich diesen Kampf führen (etwa weil Untätigkeit direkten Schaden anrichtet), kann ich ihn sinnvoll führen (das Gegenüber fragt ehrlich nach) oder sollte ich ihn vermeiden (Trolle, Ideologen, reines Gewinnen-Wollen)? Bei Gegenübern, die nur gewinnen wollen, ist jede investierte Energie vergeblich, wie Wasser in ein Fass ohne Boden. Dazu gehört auch, Debatten zu verlassen oder Feeds stummzuschalten. Die anderen Gedanken sind für sich nützlich, treffen aber nicht das Problem: Einen wahren Kern zu suchen schärft das Urteil, behebt aber nicht die Überlastung. Belegte Aussagen sind guter Stil, doch von mangelnden Belegen ist hier keine Rede. Geschichten können überzeugender sein als Zahlen, mehr Überzeugungskraft entlastet aber niemanden, der ohnehin ausgebrannt ist.","coreRule":"⚡ Erschöpfung ist ein Signal zum Umplanen, kein Beweis für Einsatz.","beleg":"Werkstück H.1.2 (Red Flags; Die Schmiede-Übung: Das Energie-Audit; Anwendung & Relevanz)","status":"entwurf","kurz":"Erschöpfung, Wut und wachsender Zynismus sind Warnzeichen für Überlastung, und Kraft ist begrenzt. Deshalb hilft es, Debatten gezielt auszuwählen und aus den übrigen auszusteigen. Der Denkfehler liegt darin, das Problem bei der Methode zu suchen statt beim Energieverbrauch.","prueffrage":"Was hat dir der bisherige Einsatz gebracht, und was hat er dich gekostet?","rueckmeldung":[{"option":0,"text":"Wut kann tatsächlich auf eigene Vorurteile hindeuten, und die Suche nach einem wahren Kern schärft das Urteil. Hier aber geht es um Überlastung: Mehr Recherche behebt sie nicht, sondern verlangt noch mehr Energie."},{"option":1,"text":"Belegte Aussagen sind guter Stil, doch von fehlenden Belegen ist im Szenario nicht die Rede. Das Problem liegt in der Erschöpfung, und zusätzlicher Prüfaufwand vor jeder Antwort würde die Last eher vergrößern."},{"option":2,"text":"Geschichten können überzeugender wirken als Zahlen. Doch bessere Überzeugungskraft entlastet niemanden, der ohnehin ausgebrannt ist: Das Problem ist der Energieverbrauch, nicht die Wahl des Mittels."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"WHO (2019): Burn-out an „occupational phenomenon“: International Classification of Diseases","oeffentlich":true,"url":"https://www.who.int/news/item/28-05-2019-burn-out-an-occupational-phenomenon-international-classification-of-diseases","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook, Abschnitt „How to talk to a conspiracy theorist“","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"a398e3cd6388b51e"}},{"id":"qx-h-017","clusterId":"H","werkstueckRef":"H.1.3","stufe":1,"question":"Was macht Jonas anders, und was ändert das für das Gespräch?","options":["Er unterstellt dem Patienten eine gute Motivation, nämlich Sorge um die eigene Gesundheit, und prüft dann die Methode selbst. So bleibt der Patient gesprächsbereit.","Er warnt den Patienten eindringlich vor den Folgen des Bleichmittels und lässt keinen Zweifel an der Gefahr. So begreift dieser die Dringlichkeit des Gesprächs.","Er bietet dem Patienten eine ungefährliche Alternative an, mit der sich sein Wunsch nach Heilung erfüllen ließe. So hat dieser einen Weg, die Idee aufzugeben.","Er stützt seine Einschätzung auf Studien und seine ärztliche Erfahrung und beruft sich auf sein Fachwissen. So folgt der Patient eher dem Experten."],"correctIndex":0,"explanation":"Jonas deutet das Motiv des Patienten wohlwollend (Sorge um die Gesundheit) und greift trotzdem die Idee an, nicht die Person. Wer sich verachtet fühlt, schaltet auf Verteidigung und hört nicht mehr zu; wer sich in seinen guten Absichten verstanden fühlt, ist eher bereit, Gegenargumente zu prüfen. Die Sachprüfung bleibt dabei vollständig erhalten: Wohlwollen gegenüber dem Motiv ersetzt weder die Kritik noch die Fakten. Das Prinzip ergänzt das logische Stahlmann-Argument um die Ebene der Motive; es ersetzt die sachliche Prüfung nicht. Die anderen Wege sind in anderer Lage sinnvoll, Jonas geht sie aber nicht: Eine eindringliche Warnung ist bei akuter Gefahr berechtigt, er lädt aber stattdessen zum gemeinsamen Prüfen ein. Eine Alternative nennt er nicht, er bleibt bei der Frage, was das Bleichmittel im Körper bewirkt. Auf Studien oder seinen ärztlichen Rang beruft er sich ebenfalls nicht, sondern schlägt vor, es gemeinsam herauszufinden.","coreRule":"⚡ Deute das Motiv wohlwollend, prüfe die Idee trotzdem hart: Barmherzigkeit gilt der Person, nicht der falschen Behauptung.","beleg":"Werkstück H.1.3 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"Ein Patient will Bleichmittel trinken, weil er fest überzeugt ist, dass es ihn von einer Krankheit heilt. Ärztin Lena reagiert: „Wie kann man nur so dumm sein?“ Arzt Jonas sagt: „Du willst unbedingt gesund werden, das verstehe ich. Lass uns gemeinsam prüfen, was Bleichmittel im Körper bewirkt.“","kurz":"Jonas deutet das Motiv wohlwollend, die Sorge um die Gesundheit, und prüft trotzdem die Methode selbst. Wer sich verachtet fühlt, verteidigt sich; wer sich verstanden fühlt, prüft Gegenargumente eher mit. Die Kritik an der Sache bleibt.","prueffrage":"Worauf zielt jede der beiden Reaktionen: auf den Patienten als Person oder auf seine Idee?","rueckmeldung":[{"option":1,"text":"Bei akuter Gefahr ist eine eindringliche Warnung durchaus berechtigt. Jonas warnt hier aber nicht, sondern lädt zum gemeinsamen Prüfen ein; entscheidend ist, dass der Patient sich nicht angegriffen fühlt und zuhört."},{"option":2,"text":"Eine Alternative anzubieten kann in anderer Lage sinnvoll sein. Jonas nennt aber keine, er bleibt bei der Frage, was das Bleichmittel im Körper bewirkt, und prüft die Methode selbst, statt sie zu ersetzen."},{"option":3,"text":"Studien und Erfahrung sind wertvoll, aber Jonas beruft sich auf keines von beiden. Er schlägt vor, es gemeinsam herauszufinden, und sein ärztlicher Rang ist dabei gar nicht der Hebel für das Gespräch."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook, Abschnitt „How to talk to a conspiracy theorist“","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"},{"typ":"url","kurz":"Malpas, J.: Donald Davidson. Stanford Encyclopedia of Philosophy (rev. 28.04.2023), Abschnitt 3.3","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"d9c5b104ae75b3c2"}},{"id":"qx-h-018","clusterId":"H","werkstueckRef":"H.1.3","stufe":2,"question":"Du willst deinen Onkel verstehen, bevor du widersprichst, ohne seine Position gutzuheißen. Von welcher Annahme gehst du dafür am besten aus?","scenario":"Im Familienchat verteidigt dein Onkel eine politische Position, die du für schädlich hältst. Du ertappst dich beim Gedanken: „Der will doch nur das Land zerstören.“ Du willst ihm trotzdem fair begegnen, ohne deine Kritik aufzugeben.","options":["Er hat seine Position wohl gründlich geprüft, darum stelle ich meine Kritik vorerst zurück.","Er folgt wohl dem Üblichen in seinem Umfeld, seine Position sagt mehr über die Gruppe.","Er verfolgt wohl ähnliche Ziele wie ich, hält aber einen anderen Weg für den richtigen.","Er handelt wohl aus Angst statt aus Überlegung, nach seinen Gründen zu fragen lohnt nicht."],"correctIndex":2,"explanation":"Wer die Position eines anderen verstehen will, deutet seine Motive zuerst im bestmöglichen Licht: gemeinsame Ziele, andere Mittel. Das ist eine plausible Annahme, und sie lässt zu, dass du die Position weiterhin für falsch und schädlich hältst. Barmherzigkeit bedeutet nicht Naivität: Wohlwollen gegenüber der Person ersetzt nicht die Beurteilung ihrer Position. Schlechte Motive wie Eigennutz zu unterstellen, ohne es beweisen zu können, ist genau die Dämonisierung, die man vermeiden will. Die anderen Annahmen passen nicht: Wer dem Onkel gründliche Prüfung unterstellt und deshalb schweigt, gibt die Kritik auf, die du behalten willst. Wer seine Haltung mit dem Umfeld erklärt, beurteilt die Herkunft statt der Gründe. Wer ihm Angst statt Überlegung unterstellt, deutet sein Inneres, ohne es zu kennen, und macht aus seiner Position ein bloßes Gefühl.","coreRule":"⚡ Wohlwollend deuten heißt nicht, die Position gutzuheißen.","beleg":"Werkstück H.1.3 (Anwendung & Relevanz: ‚Im politischen Diskurs‘; Kipppunkt; Red Flags)","status":"entwurf","kurz":"Wer verstehen will, unterstellt zuerst gemeinsame Ziele bei anderen Mitteln. So bleibt die Kritik an der Position möglich. Naheliegend, aber falsch ist, ihm Eigennutz oder böse Absicht zu unterstellen, ohne es belegen zu können.","prueffrage":"Welche Sorgen oder Erfahrungen könnten deinen Onkel zu dieser Position gebracht haben?","rueckmeldung":[{"option":0,"text":"Wohlwollen gegenüber dem Onkel ist richtig, aber hier wird es unkritisch: Dass er gründlich geprüft hat, ist unbelegt. Zudem gibst du so die Kritik auf, die du behalten willst. Verstehen und beurteilen lassen sich trennen."},{"option":1,"text":"Das Umfeld kann Überzeugungen prägen. Wer die Position aber damit erklärt, beurteilt ihre Herkunft statt seiner Gründe. Ob die Position trägt, entscheidet sich nicht an der Gruppe, und seine Gründe erfährst du so nicht."},{"option":3,"text":"Angst kann bei Überzeugungen eine Rolle spielen, doch hier wird sie bloß unterstellt, ohne dass du sie kennst. Damit wird seine Position zum Gefühl, und die Frage nach seinen Gründen erscheint sinnlos, obwohl sie dich dem Verstehen näherbrächte."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Malpas, J.: Donald Davidson. Stanford Encyclopedia of Philosophy (rev. 28.04.2023), Abschnitt 3.3","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bowell, T. & Kemp, G. (2002): Critical Thinking: A Concise Guide. London: Routledge","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"8f811561fd5a6540"}},{"id":"qx-h-019","clusterId":"H","werkstueckRef":"H.1.3","stufe":3,"question":"Was ist an dem Einwand des Freundes problematisch?","scenario":"Ein Redner schürt seit Jahren systematisch Hass gegen eine Gruppe. Du bezeichnest sein Verhalten als gefährlich. Ein Freund widerspricht: „Wir müssen barmherzig sein und von guten Absichten ausgehen.“","options":["Er unterstellt, dass wohlwollende Deutung immer gelten muss, selbst wenn wiederholtes Verhalten klar dagegen spricht.","Er beruft sich auf die Mehrheit: Weil die meisten Menschen wohlwollend deuten, müsse das auch hier ohne Prüfung gelten.","Er greift den Kritiker persönlich an, statt auf dessen Beobachtungen einzugehen, und weicht so der Sachfrage aus.","Er verallgemeinert vorschnell: Aus einem einzelnen Vorfall folgert er, dass sich der Redner stets gleich verhält."],"correctIndex":0,"explanation":"Das Prinzip der Barmherzigkeit gilt, bis das Gegenteil bewiesen ist. Wer systematisch Hass schürt, liefert genau dieses Gegenteil: Dann ist es nicht mehr barmherzig, sondern naiv, weiter von guten Absichten auszugehen. Beurteilt werden in diesem Fall die Handlungen, nicht die vermuteten Absichten. Der Fehler des Freundes liegt also darin, eine Ausgangsannahme in eine Regel zu verwandeln, die keine Beobachtung mehr korrigieren kann. Die anderen Einwände nennen bekannte Denkfehler, die im Wortwechsel aber nicht vorkommen: Der Freund beruft sich auf kein Mehrheitsargument, sondern auf eine Haltung. Er greift den Kritiker nicht persönlich an, sondern mahnt zur Barmherzigkeit. Und es geht um jahrelanges, systematisches Verhalten, nicht um einen Einzelfall, aus dem jemand vorschnell verallgemeinert.","coreRule":"⚡ Wohlwollende Deutung gilt, bis das Verhalten das Gegenteil zeigt; dann zählen die Handlungen, nicht vermutete Absichten.","quote":"Das Prinzip der Barmherzigkeit gilt, bis das Gegenteil bewiesen ist.","quoteLabel":"Merksatz:","beleg":"Werkstück H.1.3 (Der Kipppunkt)","status":"entwurf","kurz":"Wohlwollen ist eine Ausgangsannahme, die gilt, bis das Gegenteil sichtbar wird. Der Freund macht daraus eine Regel, die keine Beobachtung mehr korrigieren kann, obwohl jahrelanges systematisches Hetzen genau dieses Gegenteil zeigt.","prueffrage":"Was weiß man über den Redner aus seinem Handeln, und was wird über ihn nur vermutet?","rueckmeldung":[{"option":1,"text":"Wohlwollend zu deuten ist im Alltag tatsächlich üblich und sinnvoll, als Ausgangsannahme. Der Freund beruft sich aber gar nicht auf eine Mehrheit, sondern auf die Haltung der Barmherzigkeit, und genau diese Haltung hält er trotz der Beobachtungen aufrecht."},{"option":2,"text":"Dem Freund Ausweichen vorzuwerfen, liegt nahe, weil er auf die Beobachtungen nicht eingeht. Er greift den Kritiker aber nicht an, sondern mahnt zur Barmherzigkeit. Das Problem liegt in der Regel, auf die er sich stützt, nicht in einem Angriff auf die Person."},{"option":3,"text":"Vorschnelles Verallgemeinern ist ein häufiger Fehler, passt hier aber nicht. Es geht um jahrelanges, systematisches Verhalten, nicht um einen einzelnen Vorfall. Wer daraus ein Muster liest, schließt nicht vorschnell, sondern aus vielen Beobachtungen."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Malpas, J.: Donald Davidson. Stanford Encyclopedia of Philosophy (rev. 28.04.2023), Abschnitt 3.3","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"00df3fafbc729510"}},{"id":"qx-h-020","clusterId":"H","werkstueckRef":"H.1.3","stufe":4,"question":"Person A versteht unter Wohlwollen die wohlwollende Deutung der Aussage (dem Sprecher wahre und stimmige Überzeugungen unterstellen), Person B das Unterstellen guter Motive. Was ist an der Annahme falsch, beide meinten dasselbe?","options":["Nichts, denn wer die Aussage wohlwollend deutet, unterstellt damit automatisch auch gute Motive, und umgekehrt.","Beides ist verschieden: A betrifft die Deutung der Aussage, B die Annahme über das Motiv; das eine geht ohne das andere.","Beides ist verschieden: A meint Nachsicht gegenüber schädlichem Verhalten, B meint Nachsicht nur bei nachweislich guter Absicht.","Beides ist verschieden: A meint den Bau der stärksten Fassung eines Arguments, B meint diese Fassung nur bei gläubigen Gesprächspartnern."],"correctIndex":1,"explanation":"Wohlwollende Deutung der Aussage und wohlwollende Annahme über das Motiv sind zwei getrennte Dinge. Die sprachphilosophische Fassung des Prinzips der Nachsicht (Donald Davidson) rät, einem Sprecher wo immer plausibel wahre und in sich stimmige Überzeugungen zu unterstellen. Davon unterscheidet sich die Annahme, jemand handle aus guten Beweggründen wie Sorge oder gutem Willen. Man kann jemandes Aussage wohlwollend deuten und trotzdem seine Motive für fragwürdig halten, oder umgekehrt von guten Motiven ausgehen und die Aussage dennoch für falsch halten. Das Prinzip der intellektuellen Barmherzigkeit erweitert den Fachbegriff bewusst um die Motivebene. Wer beides gleichsetzt, verwechselt deshalb zwei Schritte, die man getrennt prüfen muss.","coreRule":"⚡ Die Aussage wohlwollend deuten und gute Motive unterstellen sind zwei verschiedene Schritte, die man getrennt prüfen kann.","beleg":"Werkstück H.1.3 (Kontext & Tiefe); Fn. gl-h-charity (Malpas, Stanford Encyclopedia of Philosophy, „Donald Davidson“, Abschn. 3.3)","status":"entwurf","scenario":"Zwei Leute streiten über die Frage, was es heißt, den Gegner wohlwollend zu behandeln. Person A sagt: „Wohlwollen heißt, dem Gegner wahre und stimmige Überzeugungen zu unterstellen.“ Person B sagt: „Wohlwollen heißt, ihm gute Motive zu unterstellen.“ Du sollst klären, ob beide dasselbe meinen.","kurz":"Aussage und Motiv sind zwei getrennte Schritte: Man kann eine Aussage wohlwollend deuten und trotzdem die Motive für fragwürdig halten, oder von guten Motiven ausgehen und die Aussage für falsch halten. Wer beides gleichsetzt, verwechselt zwei Prüfungen.","prueffrage":"Welche Wörter benutzen A und B tatsächlich, und worauf beziehen sie sich jeweils?","rueckmeldung":[{"option":0,"text":"Beides geht im Alltag oft Hand in Hand, daher wirkt es wie eine Einheit. Das eine folgt aber nicht zwingend aus dem anderen: Eine Aussage lässt sich stimmig deuten, während man die Motive anzweifelt, und umgekehrt."},{"option":2,"text":"Dass beide Positionen verschieden sind, stimmt. Die Begründung trifft aber keine von beiden: A betrifft die Deutung der Aussage, nicht Nachsicht gegenüber schädlichem Verhalten, und B nennt gute Motive, ohne einen Nachweis zur Bedingung zu machen."},{"option":3,"text":"Dass beide verschieden sind, stimmt. Doch A meint nicht den Bau der stärksten Fassung eines Arguments, und B knüpft nichts an gläubige Gesprächspartner. Der Unterschied liegt zwischen der Deutung der Aussage und der Annahme über das Motiv."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Malpas, J.: Donald Davidson. Stanford Encyclopedia of Philosophy (rev. 28.04.2023), Abschnitt 3.3","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dresner, E. (2011): The Principle of Charity and Intercultural Communication. International Journal of Communication 5, 969–982","oeffentlich":true,"url":"https://ijoc.org/index.php/ijoc/article/view/817","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"674511678a864a79"}},{"id":"qx-h-021","clusterId":"H","werkstueckRef":"H.1.4","stufe":1,"question":"Was ist an diesem Argument fehlerhaft?","options":["Es nimmt an, dass Logik allein eine Wahl treffen kann, obwohl ohne Gefühle Präferenzen, Werte und Dringlichkeit fehlen.","Es nimmt an, dass alle Menschen Gefühle gleich stark erleben, obwohl die Intensität von Gefühlen von Mensch zu Mensch stark schwankt.","Es nimmt an, dass Menschen ihre Gefühle genau durchschauen, obwohl sie deren Ursachen häufig falsch einschätzen.","Es nimmt an, dass Erfahrung für Entscheidungen unwichtig ist, obwohl Erfahrung Entscheidungen oft verbessert."],"correctIndex":0,"explanation":"Der Fallbericht widerlegt die Behauptung: Trotz intakter Intelligenz, intaktem logischem Denken und intaktem Gedächtnis konnte der Mann nicht einmal entscheiden, wie er Akten ordnen sollte. Auch bei einem Patienten mit gleichartiger Schädigung zeigte sich dasselbe Muster: Er zählte endlos Gründe für und gegen zwei Termine auf, doch ohne die emotionale Präferenz, die sagt: „Nimm einfach den!“, fand die Abwägung kein Ende. Logik kann Optionen analysieren, aber sie liefert keine Rangfolge der Ziele und kein Gefühl der Dringlichkeit. Wer Gefühle abschaltet, gewinnt deshalb keine Überlegenheit, sondern verliert Orientierung. Die anderen Optionen nennen für sich genommen zutreffende Punkte: Gefühle sind unterschiedlich stark, ihre Ursachen werden oft falsch eingeschätzt, und Erfahrung verbessert Entscheidungen. Der Sprecher stützt sich aber auf keine dieser Annahmen, und der Fallbericht zeigt etwas anderes: Intelligenz und Gedächtnis blieben erhalten, und trotzdem fehlte dem Mann die Fähigkeit, überhaupt zu wählen. Der Vorbehalt: Wie genau Gefühle in die Wahl eingreifen, etwa über Körpersignale, ist wissenschaftlich umstritten. Dass Menschen ohne Gefühlsreaktion in Entscheidungen scheitern, zeigt der Fall aber deutlich.","coreRule":"⚡ Wer Gefühle abschaltet, wird nicht klüger, sondern entscheidungsunfähig: Logik analysiert die Optionen, Gefühle geben Präferenz, Richtung und Dringlichkeit.","quote":"Emotionen sind nicht der Feind der Logik, sondern ihr notwendiger Steuermann.","quoteLabel":"Merksatz:","beleg":"Werkstück H.1.4 (Der handlungsunfähige Vulkanier; Kernidee); Fn. gl-h-2 (Damasio 1994, Descartes' Error, Elliot S. 34–51, Taschenbuchausgabe 1995)","status":"entwurf","scenario":"In einer Diskussion über Entscheidungen sagt jemand: „Gefühle stören nur. Wer seine Emotionen abschaltet, entscheidet automatisch besser. Ein Mensch, der nur noch logisch denkt, hätte alle Vorteile und würde im Alltag souverän klarkommen.“\\n\\nDazu ein Fallbericht: Ein Mann verliert nach einer Operation am Stirnhirn seine Gefühlsreaktionen. Intelligenz, logisches Denken und Gedächtnis bleiben vollständig intakt. Trotzdem grübelt er einen ganzen Nachmittag darüber, ob er Akten nach Datum, Umfang oder Bedeutung ordnen soll, und verliert seine Stelle.","kurz":"Logik kann Möglichkeiten analysieren, aber keine Rangfolge der Ziele und keine Dringlichkeit liefern. Der Fehler liegt in der Annahme, ohne Gefühle werde Entscheiden souverän, obwohl der Mann trotz intakten Denkens nicht einmal Akten ordnen konnte.","prueffrage":"Was konnte der Mann trotz intakter Intelligenz und intaktem Denken im Alltag nicht mehr leisten?","rueckmeldung":[{"option":1,"text":"Dass Gefühle unterschiedlich stark erlebt werden, stimmt. Der Sprecher will sie aber nicht dämpfen oder angleichen, sondern ganz abschalten, und genau dafür zeigt der Fallbericht das Scheitern."},{"option":2,"text":"Dass Menschen die Ursachen ihrer Gefühle oft falsch einschätzen, trifft zu. Darauf stützt sich der Sprecher aber nicht, und der Mann im Bericht scheitert nicht an Fehldeutungen, sondern daran, dass ihm die Gefühlsreaktion fehlt."},{"option":3,"text":"Erfahrung verbessert Entscheidungen oft, das stimmt. Der Sprecher sagt dazu aber nichts, und der Mann hat sein Gedächtnis vollständig behalten und kommt trotzdem nicht zu einer Wahl."}],"familie":"innehalten-bei-druck","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Dunn, Dalgleish & Lawrence (2006): The somatic marker hypothesis: A critical evaluation. Neuroscience and Biobehavioral Reviews 30(2), 239–271 (Autorenmanuskript, MRC CBU)","oeffentlich":true,"url":"https://www.mrc-cbu.cam.ac.uk/personal/tim.dalgleish/dunnsmhreview.pdf","seite":"4–5 (Manuskriptzählung)","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Damasio, A. R. (1994): Descartes' Error: Emotion, Reason, and the Human Brain. New York: Putnam","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"89e0619115d7b613"}},{"id":"qx-h-022","clusterId":"H","werkstueckRef":"H.1.4","stufe":2,"question":"Welche Antwort geht auf diese Aussage am besten ein?","scenario":"Beim Grillen sagt jemand: „Man sollte immer auf sein Herz hören und nicht auf den kalten Verstand.“ Du willst weder einfach zustimmen noch die Aussage abtun, sondern sie in einen Rahmen setzen, in dem beide Seiten ihren Platz haben.","options":["Das lässt sich prüfen: Man vergleicht Entscheidungen nach Gefühl mit Entscheidungen nach Analyse und sieht, welche besser ausgehen.","Es kommt auf die Wortwahl an: Wer mit „Herz“ die eigenen Werte meint, hat recht, wer damit bloße Launen meint, liegt falsch.","Das Wort „immer“ ist angreifbar: Schon ein Fall, in dem das Herz in die Irre führte, zeigt, dass die Aussage so nicht stimmt.","Beides wird gebraucht: Der Verstand analysiert die Optionen, das Gefühl gibt Richtung, und keines ersetzt das andere."],"correctIndex":3,"explanation":"Die Aussage setzt Herz und Verstand als Gegensatz, und beide Extreme scheitern. Ohne Gefühl fehlen Präferenzen, Werte und Dringlichkeit: Der Neurologe Antonio Damasio beschrieb Patienten mit einer Schädigung im unteren, mittleren Stirnhirn (ventromedialer präfrontaler Cortex), deren Intelligenz intakt war und die trotzdem an Banalitäten scheiterten; einer von ihnen, Elliot, grübelte einen ganzen Nachmittag darüber, wie er Akten ordnen sollte, ein anderer brauchte fast eine halbe Stunde für die Wahl zwischen zwei Terminen. Logik kann Optionen analysieren, aber nicht sagen, welches Ziel man anstreben soll. Ohne Prüfung dagegen kann ein einzelnes starkes Gefühl wie Angst oder Gier die Entscheidung kapern. Die tragfähige Antwort lässt daher beides gelten: Der Verstand analysiert die Optionen, das Gefühl gibt Richtung, und keines ersetzt das andere. Die anderen Wege sind gute Denkwerkzeuge, geben der Aussage aber keinen Rahmen: Ein Vergleich von Gefühls- und Analyseentscheidungen würde die Aussage bloß testen, ohne beiden Seiten einen Platz zu geben. Eine Begriffsklärung hilft beim Wort „Herz“, sagt aber nichts über das Zusammenspiel mit dem Verstand. Ein Gegenbeispiel zu „immer“ verwirft die Aussage, und genau das wolltest du nicht.","coreRule":"⚡ Herz und Verstand sind Partner: Der eine lenkt, der andere prüft den Weg.","beleg":"Werkstück H.1.4 (Werkbank-Frage; Kernidee; Red Flags)","status":"entwurf","kurz":"Herz und Verstand sind kein Gegensatz: Ohne Gefühl fehlen Ziele und Dringlichkeit, ohne Prüfung kann ein einzelnes starkes Gefühl die Entscheidung kapern. Der Fehler liegt darin, nur eine Seite gelten zu lassen.","prueffrage":"Wie lief deine letzte wichtige Entscheidung ab, und welche Rolle spielten dabei Bauchgefühl und Nachrechnen?","rueckmeldung":[{"option":0,"text":"Ein Vergleich von Gefühls- und Analyseentscheidungen ist ein brauchbares Prüfverfahren. Er würde die Aussage aber nur testen, ohne dem Herzen oder dem Verstand einen Platz zu geben."},{"option":1,"text":"Die Frage, was „Herz“ meinen soll, ist berechtigt, denn sie schärft das Wort. Über das Zusammenspiel mit dem Verstand sagt sie aber nichts und stellt nur die eine Deutung als richtig, die andere als falsch hin."},{"option":2,"text":"Ein einziges Gegenbeispiel genügt tatsächlich, um ein „immer“ zu widerlegen. Es verwirft die Aussage aber nur, statt ihr einen Rahmen zu geben, in dem beide Seiten ihren Platz haben."}],"familie":"innehalten-bei-druck","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Dunn, Dalgleish & Lawrence (2006): The somatic marker hypothesis: A critical evaluation (Autorenmanuskript, MRC CBU)","oeffentlich":true,"url":"https://www.mrc-cbu.cam.ac.uk/personal/tim.dalgleish/dunnsmhreview.pdf","seite":"4–5 (Manuskriptzählung)","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Damasio, A. R. (1994): Descartes' Error: Emotion, Reason, and the Human Brain. New York: Putnam","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"cc2fd8bde1382d9f"}},{"id":"qx-h-023","clusterId":"H","werkstueckRef":"H.1.4","stufe":3,"question":"Ein Kollege erzählt: „Als die Aktie über Nacht um 30 Prozent fiel, wurde mir ganz heiß vor Angst. Ich habe sofort alles verkauft, ohne nachzurechnen. Eine Stunde später stand sie wieder fast auf dem alten Kurs.“ Was erklärt am besten, warum sein Vorgehen zum Problem wurde?","options":["Die Angst hat sein Denken verdrängt und allein entschieden, sodass eine überstürzte, kurzsichtige Handlung ohne jede Prüfung der Fakten herauskam.","Ein Gefühl hat überhaupt in seine Entscheidung eingegriffen, und jedes Urteil mit Gefühlseinfluss ist grundsätzlich verzerrt und unvernünftig.","Er hat sich von einem negativen Gefühl leiten lassen, während positive Gefühle wie Freude das Urteil in solchen Lagen nie trüben.","Er hat überhaupt ein körperliches Signal bemerkt, und Körpersignale sind als Hinweise stets unzuverlässiger als eine ruhige Rechnung."],"correctIndex":0,"explanation":"Die Angst an sich war nicht das Problem. Gefühle geben Orientierung, Priorität und Dringlichkeit, und dass ihn der Kurssturz alarmiert hat, ist als Datenpunkt sogar nützlich. Zum Problem wurde die Lage erst, als die starke Emotion das Nachdenken komplett ersetzt hat: Er hat weder nachgerechnet noch Gründe für oder gegen den Verkauf geprüft. Dann entscheidet das Gefühl allein, und das Ergebnis sind impulsive, kurzsichtige Handlungen. Ein Denken ganz ohne Gefühl wäre dagegen nicht besser, sondern orientierungslos: Patienten mit gestörter Verbindung zwischen Gefühl und Verstand zerdenken schon einfache Terminwahlen endlos. Sinnvoll ist, das Gefühl ernst zu nehmen und dann zu prüfen, welche Fakten es stützen oder widerlegen.","coreRule":"⚡ Gefühle beraten gut, aber sie dürfen nicht allein regieren.","beleg":"Werkstück H.1.4 (Der Kipppunkt; Red Flags: emotionale Kaperung)","status":"entwurf","scenario":"","kurz":"Die Angst selbst war ein brauchbarer Alarm. Zum Problem wurde, dass sie das Nachdenken ersetzt hat: Er prüfte weder Zahlen noch Gründe, und dann entscheidet das Gefühl allein, was oft zu impulsiven, kurzsichtigen Handlungen führt.","prueffrage":"Was geschah zwischen dem Moment, in dem er den Kurssturz sah, und dem Verkauf?","rueckmeldung":[{"option":1,"text":"Dass ein Gefühl mitredet, ist nicht das Problem, denn Gefühle liefern Orientierung und Dringlichkeit, und die Angst war hier sogar ein nützlicher Alarm. Verzerrt wird das Urteil erst, wenn das Gefühl die Prüfung der Fakten ersetzt."},{"option":2,"text":"Auf die Art des Gefühls kommt es nicht an: Auch Freude kann das Urteil überstimmen, wenn sie die Prüfung ersetzt. Entscheidend ist, ob das Gefühl allein entscheidet oder ob man es mit Fakten gegenprüft."},{"option":3,"text":"Das Körpersignal zu bemerken war nicht der Fehler, es zeigt, dass etwas Wichtiges passiert ist. Ein Denken ohne solche Signale wäre nicht besser, sondern orientierungslos. Problematisch ist nur, es ungeprüft in eine Handlung umzusetzen."}],"familie":"innehalten-bei-druck","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Dunn, Dalgleish & Lawrence (2006): The somatic marker hypothesis: A critical evaluation (Autorenmanuskript, MRC CBU)","oeffentlich":true,"url":"https://www.mrc-cbu.cam.ac.uk/personal/tim.dalgleish/dunnsmhreview.pdf","seite":"4–5 (Manuskriptzählung)","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Peters, E. (2011): Affect and Emotion. In: Fischhoff, Brewer & Downs (Hg.): Communicating Risks and Benefits: An Evidence-Based User's Guide. FDA","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"24c6fc66441ac201"}},{"id":"qx-h-024","clusterId":"H","werkstueckRef":"H.1.4","stufe":4,"question":"Eine Wissenschaftsjournalistin schreibt: „Der Neurologe Antonio Damasio hat bewiesen, dass Körpersignale unsere Entscheidungen lenken. Der Beweis ist ein Kartenspiel-Experiment.“ Welche Rückfrage prüft diese Behauptung am besten?","options":["Wer hat das Experiment bezahlt, und hätte der Geldgeber ein Interesse an einem bestimmten Ergebnis gehabt?","Lässt sich das Ergebnis auch ohne Körpersignale erklären, etwa weil die Teilnehmer die Strategie bewusst kannten?","Wurde die Studie vor der Veröffentlichung von unabhängigen Fachleuten begutachtet, und wo ist sie erschienen?","Hat die Journalistin die Originalarbeit selbst gelesen oder nur eine Zusammenfassung davon übernommen?"],"correctIndex":1,"explanation":"Wer „bewiesen“ sagt, muss ausschließen, dass es eine einfachere Erklärung für dasselbe Ergebnis gibt. Genau das ist hier fraglich: Maia und McClelland (2004) fanden, dass Teilnehmer dieses Kartenspiels die günstige Strategie bewusst kennen, und zwar zuverlässiger, als sie danach handeln. Dann lässt sich das Verhalten möglicherweise auch ohne unbewusste Körpersignale erklären. Dunn u. a. (2006) kommen zu dem Schluss, dass die Einwände die Hypothese nicht widerlegen; sie sei eine elegante Theorie, die zusätzliche empirische Stützung braucht. „Bewiesen“ ist also zu stark. Gesichert ist nur: Die Hypothese ist einflussreich, aber umstritten, und bislang weder bewiesen noch widerlegt. Die anderen Rückfragen sind für sich sinnvoll, klären aber nicht, ob die Deutung des Ergebnisses trägt: Die Frage nach dem Geldgeber zielt auf mögliche Befangenheit, wofür das Szenario keinen Hinweis gibt. Eine Begutachtung spricht für Sorgfalt, ist aber noch kein Beweis für die Deutung. Ob die Journalistin das Original gelesen hat, betrifft ihre Quelle, nicht die Frage, ob eine sparsamere Erklärung offen bleibt.","coreRule":"⚡ Bevor du „bewiesen“ akzeptierst, frage: Gibt es eine einfachere Erklärung für dasselbe Ergebnis?","beleg":"Werkstück H.1.4 (Kernidee; Kontext & Tiefe); Fn. gl-h-somatisch (Damasio 1994, Kap. 8–9; Dunn/Dalgleish/Lawrence 2006, S. 239–271; Maia/McClelland 2004, PNAS 101(45), S. 16075–16080, hier S. 16075)","status":"entwurf","scenario":"Die Hypothese besagt, dass Körpersignale („somatische Marker“) Entscheidungen lenken, noch bevor wir die Regeln bewusst durchschauen. Als zentraler Beleg gilt ein Kartenspiel-Experiment, in dem gesunde Testpersonen und Patienten mit Schäden im Stirnhirn aus vier Kartenstapeln mit unterschiedlichem Gewinn- und Verlustrisiko ziehen.","kurz":"„Bewiesen“ verlangt, dass keine einfachere Erklärung übrig bleibt. Hier ist offen, ob die Teilnehmer die günstige Strategie schlicht bewusst kannten. Dann bräuchte es keine unbewussten Körpersignale, und die Hypothese bleibt umstritten.","prueffrage":"Was genau taten die Testpersonen im Kartenspiel, und was davon wurde tatsächlich gemessen?","rueckmeldung":[{"option":0,"text":"Wer zahlt, kann ein Ergebnis färben, und diese Frage gehört zur Quellenkritik. Im Szenario steht dazu aber nichts, und sie sagt auch nicht, ob die Deutung „Körpersignale lenken Entscheidungen“ das Ergebnis wirklich erklärt."},{"option":2,"text":"Eine Begutachtung durch Fachleute spricht für Sorgfalt, das stimmt. Sie macht aus einer Deutung aber noch keinen Beweis. Veröffentlichte Studien können umstritten bleiben, so wie diese: Offen ist, ob eine sparsamere Erklärung genügt."},{"option":3,"text":"Die Primärquelle zu lesen ist eine gute Gewohnheit. Doch auch eine genau gelesene Studie kann zu stark zusammengefasst werden. Entscheidend ist hier nicht, was die Journalistin gelesen hat, sondern ob das Wort „bewiesen“ durch die Befunde gedeckt ist."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Maia, T. V. & McClelland, J. L. (2004): A reexamination of the evidence for the somatic marker hypothesis. PNAS 101(45), 16075–16080 (PMC-Fassung)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC528759/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dunn, Dalgleish & Lawrence (2006): The somatic marker hypothesis: A critical evaluation (Autorenmanuskript, MRC CBU)","oeffentlich":true,"url":"https://www.mrc-cbu.cam.ac.uk/personal/tim.dalgleish/dunnsmhreview.pdf","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e46e21fbbe16fb33"}},{"id":"qx-h-025","clusterId":"H","werkstueckRef":"H.1.5","stufe":1,"question":"Welche Schlussfolgerung ist am besten begründet?","options":["Beide überziehen: Dass Gewohnheiten die Konzentration prägen, ist plausibel, wie stark sich das im Gehirn zeigt, aber offen. Training kann helfen, am ehesten an der gefragten Tätigkeit.","Die Schwester hat recht: Jahrelange Gewohnheiten prägen das Gehirn, und was sich dabei eingeschliffen hat, lässt sich im Erwachsenenalter durch Üben nicht mehr zurückholen.","Der Bruder hat recht: Das Gehirn bleibt ein Leben lang lernfähig, und schon bloßes Üben genügt, um die frühere Konzentrationsfähigkeit sicher und vollständig zurückzuholen.","Keiner von beiden liegt richtig, solange keine Hirnscans vorliegen: Ohne sie ist jede Aussage darüber, ob Feeds schaden oder Training hilft, bloße Spekulation."],"correctIndex":0,"explanation":"Die Schwester nimmt an, das erwachsene Gehirn sei starr. Das ist überholt: Auch das erwachsene Gehirn verändert sich durch Erfahrung, wie stark und wie dauerhaft, ist allerdings umstritten; ihr „da lässt sich nichts mehr machen“ ist daher zu sicher. Der Bruder liegt in der Richtung näher an der Sache, denn Konzentration lässt sich üben, am ehesten an genau der Tätigkeit, für die man sie braucht; dass Üben es sicher und vollständig wieder richtet, ist aber ebenso wenig gesichert, und beliebig formbar ist das Gehirn nicht. Dass jahrelange Feed-Gewohnheiten die Konzentration geschwächt haben, ist plausibel, ob und wie stark sich das im Gehirn selbst zeigt, ist offen. Die anderen Schlüsse haben je einen richtigen Kern, ziehen daraus aber zu viel: Dass Gewohnheiten das Gehirn prägen, heißt nicht, dass sich nichts mehr zurückbilden lässt. Dass das Gehirn lernfähig bleibt, heißt nicht, dass Üben allein alles zurückholt. Und ohne Hirnscans lässt sich zwar nicht sagen, wie stark sich Feeds im Gehirn zeigen, wohl aber, dass das Üben einer Tätigkeit sie in der Regel verbessert.","coreRule":"⚡ Das Gehirn formt sich nach dem, was du wiederholst, ohne Rücksicht auf den Nutzen. Wie stark und wie dauerhaft, bleibt eine offene Frage.","quote":"","quoteLabel":"","beleg":"Werkstück H.1.5 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"Jemand verbringt seit Jahren fast jede freie Minute mit kurzen Videos und Nachrichten-Feeds. Heute fällt es ihm schwer, länger als ein paar Minuten bei einem anspruchsvollen Text zu bleiben. Seine Schwester sagt: „Ich bin mir sicher, dass sich sein Gehirn dadurch dauerhaft verschlechtert hat, da lässt sich nichts mehr machen.“ Er antwortet: „Das glaube ich nicht. Ich muss nur wieder üben, dann wird es besser.“","kurz":"Dass Feed-Gewohnheiten die Konzentration geschwächt haben, ist plausibel, wie stark sich das im Gehirn zeigt, aber offen. Üben hilft in der Regel, am ehesten an der gefragten Tätigkeit. „Nichts mehr zu machen“ wie „sicher wieder wie früher“ sind beide zu sicher.","prueffrage":"Was lässt sich in seinem Alltag tatsächlich beobachten, wenn er statt Feeds regelmäßig längere Texte liest?","rueckmeldung":[{"option":1,"text":"Dass jahrelange Gewohnheiten die Konzentration und das Gehirn prägen, ist plausibel. Daraus folgt aber nicht, dass sich nichts mehr zurückbilden lässt: Auch das erwachsene Gehirn verändert sich durch Erfahrung, nur wie weit, ist offen."},{"option":2,"text":"Daran stimmt: Das Gehirn bleibt lernfähig, und Konzentration lässt sich üben. „Sicher und vollständig“ geht aber zu weit, denn dass Üben allein alles zurückholt, ist nicht gesichert, und beliebig formbar ist das Gehirn nicht."},{"option":3,"text":"Hirnscans fehlen tatsächlich, und wie stark sich Feeds im Gehirn zeigen, bleibt offen. Daraus folgt aber nicht, dass alles Spekulation ist: Dass Üben einer Tätigkeit sie in der Regel verbessert, lässt sich auch ohne Scans sagen."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Malik, Stemplewski & Maciaszek (2022): The Effect of Juggling as Dual-Task Activity on Human Neuroplasticity: A Systematic Review. Int. J. Environ. Res. Public Health 19(12), 7102","oeffentlich":true,"doi":"10.3390/ijerph19127102","abruf":"2026-10-12"},{"typ":"doi","kurz":"Fan, Wu, Fossella & Posner (2001): Assessing the heritability of attentional networks. BMC Neuroscience 2, 14","oeffentlich":true,"doi":"10.1186/1471-2202-2-14"},{"typ":"literatur","kurz":"Thomas, C. & Baker, C. I. (2013): Teaching an adult brain new tricks: a critical review of evidence for training-dependent structural plasticity in humans. NeuroImage 73, 225–236","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"b87f69bf86b5efc2"}},{"id":"qx-h-026","clusterId":"H","werkstueckRef":"H.1.5","stufe":2,"question":"Welcher Plan ist am ehesten geeignet, Konzentration wieder aufzubauen, und warum?","scenario":"Du merkst, dass du kaum noch ein langes Buch am Stück lesen kannst und bei jeder Mikropause zum Smartphone greifst. Du willst deine Konzentration gezielt trainieren und überlegst, wie du vorgehst.","options":["Jeden Tag 15 bis 30 Minuten ununterbrochen eine einzige anspruchsvolle Aufgabe bearbeiten, ohne Smartphone in Sichtweite, und das konsequent wiederholen.","Jeden Tag 20 Minuten Denkspiele auf dem Tablet spielen, in der Hoffnung, dass sich die Konzentration später auch beim Lesen langer Texte verbessert.","Jeden Tag eine Stunde ein Hörbuch laufen lassen und nebenbei andere Dinge erledigen, um das Zuhören und das Dranbleiben über längere Zeit zu üben.","Jeden Tag zehn Minuten achtsam atmen, in der Hoffnung, dass sich die Ruhe auch auf lange Lesephasen überträgt, und sonst nichts verändern."],"correctIndex":0,"explanation":"Geübt wird, was man tatsächlich tut: Wer Konzentration will, muss genau diese Tätigkeit regelmäßig und in kleinen, machbaren Dosen üben. Sinnvoll sind dafür tägliche, ununterbrochene Übungsphasen von 15 bis 30 Minuten. Am Anfang wird das Gehirn rebellieren und nach Ablenkung verlangen, mit konsequenter Wiederholung wird der Weg der Konzentration aber wieder frei. Unterschiede in der Aufmerksamkeitssteuerung sind zum Teil erblich, aber auch geübt werden kann sie; besser wird man dabei vor allem in dem, was man übt, ohne sicheren Übertrag auf ungeübte Aufgaben (Owen u. a. 2010). Für die Übung der Konzentration spricht also einiges; ob ständige Ablenkung das Gehirn messbar umgebaut hat, ist dagegen noch offen. Die anderen Pläne klingen vernünftig, passen aber nicht: Denkspiele verbessern vor allem das Spielen dieser Spiele, ein sicherer Übertrag aufs Lesen ist nicht belegt. Ein Hörbuch nebenbei übt geteilte Aufmerksamkeit, nicht das ununterbrochene Dranbleiben an einer Aufgabe. Eine Atemübung kann entspannen, ersetzt aber nicht das Üben der Tätigkeit, um die es geht.","coreRule":"⚡ Wer eine Fähigkeit stärken will, übt sie regelmäßig und gezielt an genau der Tätigkeit, für die er sie braucht.","beleg":"Werkstück H.1.5 (Die Schmiede-Übung; Anwendung & Relevanz); Fn. gl-h-aufmerksamkeit (Fan u. a. 2001; Rueda u. a. 2005)","status":"entwurf","kurz":"Konzentration wird dadurch besser, dass man sie genau so übt: täglich 15 bis 30 Minuten ununterbrochen an einer Aufgabe bleiben, ohne Smartphone in Reichweite. Verführerisch ist, Ersatzübungen zu wählen, denn besser wird man vor allem in dem, was man tatsächlich übt.","prueffrage":"Was genau tust du während der Zeit, die du als Training einplanst, und wie oft kommt das vor?","rueckmeldung":[{"option":1,"text":"Denkspiele trainieren etwas, aber vor allem das Spielen dieser Spiele. Ein sicherer Übertrag aufs Lesen langer Texte ist nicht belegt, und der Bildschirm bleibt in Reichweite."},{"option":2,"text":"Zuhören und Dranbleiben sind ein sinnvolles Ziel. Wer nebenbei andere Dinge erledigt, übt aber geteilte Aufmerksamkeit, nicht das ununterbrochene Bleiben an einer einzigen Aufgabe."},{"option":3,"text":"Achtsames Atmen kann entspannen. Der Plan verändert aber sonst nichts und übt das Lesen selbst nicht, es bleibt bei der Hoffnung auf einen Übertrag von der Ruhe auf lange Lesephasen."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Owen, Hampshire, Grahn u. a. (2010): Putting brain training to the test. Nature 465(7299), 775–778 (frei als PMC2884087)","oeffentlich":true,"doi":"10.1038/nature09042","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rueda, Rothbart, McCandliss, Saccomanno & Posner (2005): Training, maturation, and genetic influences on the development of executive attention. PNAS 102(41), 14931–14936 (frei als PMC1253585)","oeffentlich":true,"doi":"10.1073/pnas.0506897102","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"62f25886e12b2c9a"}},{"id":"qx-h-027","clusterId":"H","werkstueckRef":"H.1.5","stufe":3,"question":"Welche Schlussfolgerung stützt eine große Online-Studie mit über 11.000 Teilnehmern, in der sechs Wochen lang Denkspiele geübt wurden, am besten?","scenario":"Ein Werbetext verspricht: „Zehn Minuten Gehirntraining täglich verbessern Ihre Konzentration im ganzen Alltag.“ Zur Prüfung des Versprechens liegt eine große Online-Studie vor: Über 11.000 Menschen übten sechs Wochen lang Denkspiele. Alle geübten Aufgaben wurden deutlich besser. Bei ungeübten Aufgaben, auch bei eng verwandten, zeigte sich keine Verbesserung.","options":["Wer eine Aufgabe übt, wird vor allem in dieser Aufgabe besser; für ungeübte Aufgaben belegt die Studie keinen Gewinn.","Wer verteilt statt am Stück übt, behält länger; die Studie belegt den Vorteil dieser zeitlichen Verteilung des Übens.","Wer schon gut ist, gewinnt durch Übung weniger dazu; die Studie belegt, dass bessere Ausgangswerte den Zuwachs bremsen.","Wer allgemeine Denkspiele übt, stärkt seine Konzentration überall; die Studie macht das durch ihre hohe Teilnehmerzahl verlässlich."],"correctIndex":0,"explanation":"Die Teilnehmer wurden in den geübten Aufgaben deutlich besser, in ungeübten Aufgaben aber nicht, selbst wenn diese den geübten kognitiv nahestanden. Das stützt: Übung wirkt vor allem dort, wo geübt wurde. Der Werbeslogan behauptet aber genau den Sprung vom Spiel auf den „ganzen Alltag“. Dafür fehlt hier der Beleg. Wer Konzentration für eine bestimmte Tätigkeit braucht, übt sie deshalb am besten an dieser Tätigkeit selbst. Dass Aufmerksamkeit trainierbar ist, bleibt davon unberührt: Die geübten Aufgaben wurden ja besser. Dass verteiltes Üben das Behalten fördert, ist gut belegt, wurde in dieser Studie aber gar nicht verglichen. Ob bessere Ausgangswerte den Zuwachs bremsen, lässt sich aus dem Beschriebenen nicht ablesen. Eine hohe Teilnehmerzahl macht ein Ergebnis verlässlicher, kann den fehlenden Gewinn bei den ungeübten Aufgaben aber nicht in einen Nutzen verwandeln.","coreRule":"⚡ Übung wirkt vor allem im Geübten: Trainiere Konzentration an der Tätigkeit, die du brauchst, nicht an Ersatzspielen.","beleg":"Werkstück H.1.5 (Kontext & Tiefe: Konzentration als Fähigkeit); Fn. gl-h-aufmerksamkeit (Owen u. a. 2010, Nature 465(7299), S. 775–778)","status":"entwurf","kurz":"Die Studie zeigt Fortschritte nur in den geübten Aufgaben, nicht in ungeübten, auch nicht in eng verwandten. Der Schritt vom Spiel zum „ganzen Alltag“ ist damit nicht belegt: Übung wirkt vor allem dort, wo geübt wurde.","prueffrage":"In welchen Aufgaben genau zeigte sich eine Verbesserung, und wie weit liegen diese vom beworbenen „ganzen Alltag“ entfernt?","rueckmeldung":[{"option":1,"text":"Dass verteiltes Üben das Behalten fördert, ist gut belegt. Hier wurde aber gar nicht verglichen, wie die Übung über die Zeit verteilt war, also kann diese Studie den Vorteil nicht zeigen."},{"option":2,"text":"Dass Übung bei guten Ausgangswerten weniger bringt, klingt plausibel. Die Studie beschreibt aber keine Unterschiede nach Ausgangsniveau, ihr Vergleich lief zwischen geübten und ungeübten Aufgaben. Diese Aussage lässt sich daraus nicht ablesen."},{"option":3,"text":"Die große Teilnehmerzahl macht ein Ergebnis verlässlicher, hier also den Befund, dass ungeübte Aufgaben nicht besser wurden. Ein fehlender Gewinn wird durch viele Teilnehmer nicht zum Nutzen. Die Studie widerspricht der Aussage sogar."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Owen, Hampshire, Grahn u. a. (2010): Putting brain training to the test. Nature 465(7299), 775–778 (frei als PMC2884087)","oeffentlich":true,"doi":"10.1038/nature09042","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"de201f691997fa2e"}},{"id":"qx-h-028","clusterId":"H","werkstueckRef":"H.1.5","stufe":4,"question":"In einem Vortrag zitiert jemand den Satz „Neurons that fire together, wire together“ und fügt hinzu: „Das hat Donald Hebb 1949 wörtlich so geschrieben.“ Du willst die Aussage prüfen. Welche Überlegung bringt dich am weitesten?","options":["Ob die Aussage heute als wissenschaftlich gesichert gilt, entscheidet über ihr Gewicht, das lässt sich in neueren Studien prüfen.","Eine so eingängige Formel stammt eher aus einer späteren Zusammenfassung, das lässt sich an der Originalquelle prüfen.","Wer fachkundig vorträgt, zitiert meist genauer, das lässt sich an Beruf und Veröffentlichungen der Person prüfen.","Vortragende wählen Zitate oft nach ihrem eigenen Interesse aus, das lässt sich an den Absichten hinter dem Vortrag prüfen."],"correctIndex":1,"explanation":"Eine Zuschreibung ist erst belegt, wenn man die Originalquelle kennt. Hier ist das besonders wichtig: Die Formel ist so griffig, dass sie eher wie eine spätere Verdichtung klingt als wie ein Satz aus einer Fachpublikation. Tatsächlich ist die Kurzformel keine Originalformulierung Hebbs („The Organization of Behavior“, 1949), sondern eine spätere, griffigere Zusammenfassung seines Postulats. Sie wird meist Carla Shatz zugeschrieben („cells that fire together wire together“, Scientific American, 1992); populär wurde sie erst rund vier Jahrzehnte nach Hebb. Hebbs eigener Wortlaut ist deutlich sperriger: Wenn das Axon einer Zelle A nah genug ist, um eine Zelle B zu erregen, und wiederholt an deren Aktivierung beteiligt ist, tritt in einer oder beiden Zellen ein Wachstums- oder Stoffwechselprozess ein, der die Effizienz von A bei der Erregung von B erhöht. Selbst inhaltlich trifft die Kurzformel Hebb nur ungefähr: Bei ihm ist A an der Erregung von B ursächlich beteiligt, die Formel spricht nur von gleichzeitigem Feuern. Die Behauptung „wörtlich so geschrieben“ stimmt jedenfalls nicht. Ob die Theorie heute als gesichert gilt, ist eine eigene, sinnvolle Frage, sie sagt aber nichts darüber, wer diese Worte geschrieben hat. Wie fachkundig jemand ist, ersetzt den Blick in die Quelle nicht, denn auch Fachleute geben Sätze ungenau wieder. Und selbst wenn man die Absichten der Person kennt, weiß man noch nicht, was Hebb tatsächlich formuliert hat.","coreRule":"⚡ Griffige Zitate prüfen: Je eingängiger die Formel, desto eher lohnt der Blick in die Originalquelle, bevor man sie einer Person zuschreibt.","beleg":"Werkstück H.1.5 (Kontext & Tiefe); Fn. gl-h-3 (Hebb, The Organization of Behavior, 1949; Shatz, Scientific American, September 1992)","status":"entwurf","scenario":"","kurz":"Eine Zuschreibung ist erst belegt, wenn man die Originalquelle kennt. Der Satz ist so griffig, dass er eher nach späterer Verdichtung klingt als nach einer Fachpublikation. Tatsächlich stammt die Kurzformel nicht von Hebb selbst, sondern ist eine spätere Zusammenfassung.","prueffrage":"Behauptet der Vortragende nur, dass der Gedanke von Hebb stammt, oder auch, dass Hebb genau diese Worte benutzt hat?","rueckmeldung":[{"option":0,"text":"Ob die Theorie heute als gesichert gilt, ist eine sinnvolle Frage, und Studien können sie beantworten. Sie sagt aber nichts darüber, wer diese Worte wann geschrieben hat, und genau das wurde behauptet."},{"option":2,"text":"Fachleute zitieren oft genauer, das stimmt. Aber auch sie geben Sätze ungenau oder aus zweiter Hand wieder; Beruf und Veröffentlichungen ersetzen deshalb den Blick in die Quelle nicht."},{"option":3,"text":"Zitate werden tatsächlich oft nach Interesse ausgewählt, und das kann die Skepsis schärfen. Selbst wenn du die Absichten kennst, weißt du noch nicht, was Hebb formuliert hat; dafür führt kein Weg an der Quelle vorbei."}],"familie":"zitat-am-original-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Liberman, M. (21.04.2016): Language Log, Beitrag zu „fire together, wire together“","oeffentlich":true,"url":"https://languagelog.ldc.upenn.edu/nll/?p=25194","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Hebb, D. O. (1949): The Organization of Behavior. New York: Wiley","oeffentlich":false},{"typ":"literatur","kurz":"Shatz, C. J. (1992): The developing brain. Scientific American 267(3)","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"68dcc3be5589cc5a"}},{"id":"qx-h-029","clusterId":"H","werkstueckRef":"H.1.6","stufe":1,"question":"Was erklärt am besten, warum du ihr nicht helfen konntest und selbst erschöpft bist?","scenario":"Tante Gerda ruft panisch an: „Die da oben vergiften das Trinkwasser!“ Du hörst zu und schwingst ganz mit ihr mit: Ihre Angst wird zu deiner Angst, ihre Wut zu deiner Wut. Nach dem Anruf zitterst du, fühlst dich hoffnungslos und erschöpft. Gerda hat sich nicht beruhigt, und dir graut vor dem nächsten Anruf.","options":["Du hast ihre Gedanken kühl zerlegt und ihre Gefühle ausgeblendet, daher spürte sie keine Zuwendung und du bliebst innerlich leer.","Du hast ihr scharf widersprochen und dadurch Gegenwehr ausgelöst, daher verhärtete sich ihre Überzeugung und der Streit zehrte an dir.","Du hast ihre Panik übernommen statt dich davon zu lösen, daher warst du selbst überwältigt und konntest ihr keinen ruhigen Halt bieten.","Du hast dich sofort abgegrenzt und ihre Gefühle auf Abstand gehalten, daher fühlte sie sich zurückgewiesen und du warst ausgelaugt."],"correctIndex":2,"explanation":"Wer die Gefühle des anderen ungefiltert übernimmt, schwingt voll mit ihm mit. Bei Panik heißt das: Zwei Menschen sind gleichzeitig aufgewühlt, und keiner ist übrig, der Halt geben könnte. Dieses Mitschwingen kann zu „Empathic Distress“ führen, einer emotionalen Überwältigung, die bis zu Lähmung, Rückzug oder Burnout reichen kann. Wer dagegen die Angst versteht, ohne sie zu übernehmen, und ruhig, aber warm bleibt, kann tatsächlich helfen; die Erschöpfung kommt hier nicht vom Sorgen an sich, sondern vom Übernehmen fremder Panik. Kühles Zerlegen ihrer Gedanken würde ein anderes Problem erzeugen, passt aber nicht dazu, dass du ganz mit ihr mitgeschwungen bist. Scharfer Widerspruch kann Gegenwehr auslösen, doch von einem Streit ist im Szenario keine Rede. Und wer sich sofort abgrenzt, schwingt gerade nicht mit, während hier das Mitschwingen die Erschöpfung erklärt.","coreRule":"⚡ Wer die Panik des anderen spiegelt, kann ihm nicht helfen: Verstehen und Fürsorge brauchen Abstand zum fremden Gefühl.","beleg":"Werkstück H.1.6 (Der Anruf bei Tante Gerda, Szenario 1; Kontext & Tiefe)","status":"entwurf","kurz":"Wer Panik ungefiltert übernimmt, ist genauso aufgewühlt wie das Gegenüber, und dann bleibt niemand, der Halt geben kann. Nicht das Sorgen erschöpft, sondern das Übernehmen fremder Panik. Verstehen ohne Übernehmen, ruhig und warm, hilft eher.","prueffrage":"Was hast du während des Anrufs gesagt oder getan, das Gerda hätte beruhigen können?","rueckmeldung":[{"option":0,"text":"Gedanken kühl zu zerlegen und Gefühle auszublenden kann tatsächlich leer machen und Nähe verhindern. Im Szenario bist du aber gerade nicht auf Abstand, sondern schwingst ganz mit ihr mit, daher erklärt dieser Weg deinen Zustand nicht."},{"option":1,"text":"Scharfer Widerspruch kann Gegenwehr auslösen und eine Überzeugung verhärten. Von einem Streit steht im Szenario aber nichts: Du hörst zu und teilst ihre Gefühle, daher liegt die Erschöpfung nicht im Konflikt."},{"option":3,"text":"Wer sich sofort abgrenzt, kann sich tatsächlich ausgelaugt fühlen und Nähe verspielen. Hier aber hältst du ihre Gefühle nicht fern, sondern nimmst sie voll in dich auf, und genau das passt nicht zu einer Abgrenzung."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Klimecki, Leiberg, Ricard & Singer (2014): Differential Pattern of Functional Brain Plasticity After Compassion and Empathy Training. Social Cognitive and Affective Neuroscience 9(6)","oeffentlich":true,"doi":"10.1093/scan/nst060","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4040103/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Singer & Klimecki (2014): Empathy and Compassion. Current Biology 24(18), R875–R878 (Verlagsseite hier nicht geöffnet; Register b2a0fd0f299 am Volltext bestätigt)","oeffentlich":false,"doi":"10.1016/j.cub.2014.06.054"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"3ea66cf2e0078c32"}},{"id":"qx-h-030","clusterId":"H","werkstueckRef":"H.1.6","stufe":2,"question":"Wie reagierst du in diesem Gespräch am besten?","options":["Du überlegst, warum sie das glaubt, sagst dann kurz, dass du ihre Angst wahrnimmst, und bleibst danach ruhig und zugewandt, um ihr beim Einordnen zu helfen.","Du schickst ihr Berichte über die Trinkwasserkontrollen und bittest sie, in Ruhe nachzulesen, damit sie sich selbst ein Bild machen und die Lage einordnen kann.","Du bittest sie, sich erst zu beruhigen und später noch einmal anzurufen, weil Gespräche in der Panik meist wenig bringen und ihr so besser geholfen ist.","Du fragst zuerst nach, woher sie ihre Informationen hat, und gehst jede Quelle einzeln mit ihr durch, bevor du auf ihre Angst eingehst, um Klarheit zu schaffen."],"correctIndex":0,"explanation":"Hilfreich ist eine Abfolge: erst verstehen, warum die Person so denkt, dann ihr Gefühl kurz spiegeln („Ich höre, dass dir das Angst macht“) und schließlich ruhig und warm Halt geben. Das kurze Spiegeln signalisiert, dass du ihre Angst ernst nimmst, ohne dass sie auf dich übergeht. Berichte nachzulesen hilft, wenn jemand wieder ruhig ist; mitten in der Panik kommt das nicht an. Auf später zu verschieben lässt sie mit ihrer Angst allein, obwohl du ihr jetzt helfen willst. Zuerst Quellen abzufragen wirkt wie ein Verhör und übergeht ihr Gefühl.","coreRule":"⚡ Verstehen, kurz spiegeln, dann ruhig und warm Halt geben.","quote":"Du fühlst nicht mit ihr, du fühlst für sie.","quoteLabel":"Merksatz:","beleg":"Werkstück H.1.6 (Szenario 3: Die Warme Brücke; Kontext & Tiefe: strategische Abfolge)","status":"entwurf","scenario":"Deine Tante ruft dich panisch an: Sie ist überzeugt, dass „die da oben“ das Trinkwasser vergiften. Sie redet schnell, ihre Stimme zittert. Du willst ihr helfen, ohne selbst in ihre Panik hineingezogen zu werden und ohne sie wie einen Fall zu behandeln.","kurz":"Hilfreich ist eine Abfolge: erst verstehen, warum sie so denkt, dann ihre Angst kurz benennen, dann ruhig und warm Halt geben. Dass Fakten nützlich sind, stimmt, aber mitten in der Panik kommen sie meist nicht an.","prueffrage":"Was hättest du an ihrer Stelle in diesem Moment von der Person am anderen Ende der Leitung gebraucht?","rueckmeldung":[{"option":1,"text":"Verlässliche Berichte sind ein guter Gedanke, sobald deine Tante wieder ruhig ist. Mitten in der Panik kommen sie aber nicht an, und ihre Angst bliebe im Gespräch unbeachtet."},{"option":2,"text":"Das wirkt rücksichtsvoll, und aufgewühlt lässt sich tatsächlich schwer klären. Deine Tante bliebe so aber allein mit ihrer Angst, obwohl du ihr jetzt helfen willst."},{"option":3,"text":"Zu wissen, woher die Informationen stammen, hilft beim Verstehen. Jede Quelle einzeln durchzugehen, bevor ihre Angst zur Sprache kommt, wirkt aber wie ein Verhör und übergeht ihr Gefühl."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Klimecki, Leiberg, Ricard & Singer (2014): Differential Pattern of Functional Brain Plasticity After Compassion and Empathy Training. Social Cognitive and Affective Neuroscience 9(6)","oeffentlich":true,"doi":"10.1093/scan/nst060","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4040103/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Singer & Klimecki (2014): Empathy and Compassion. Current Biology 24(18), R875–R878 (Verlagsseite hier nicht geöffnet; Register b2a0fd0f299 am Volltext bestätigt)","oeffentlich":false,"doi":"10.1016/j.cub.2014.06.054"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"df79dca1a16e44a6"}},{"id":"qx-h-031","clusterId":"H","werkstueckRef":"H.1.6","stufe":3,"question":"Wo liegt das Risiko in dieser Haltung des Kollegen?","scenario":"Ein Kollege sagt über seinen Onkel, der an eine Verschwörungserzählung glaubt: „Ich durchschaue seine Logik perfekt und kann jeden Schritt nachvollziehen. Aber er wirft mir vor, kalt zu sein, und fühlt sich wie unter dem Mikroskop.“","options":["Er fühlt zu stark mit dem Onkel mit; so droht ihm Überforderung und am Ende der Rückzug aus dem Gespräch und der Beziehung.","Er sucht nur Belege, die seine Sicht stützen, und blendet Gegenbelege aus; so wird sein Bild vom Onkel einseitig und ungerecht.","Er nutzt das Verstehen nur zum Analysieren, ohne Fürsorge für den Onkel; so wirkt es wie Sezieren und dient nicht mehr dem Helfen.","Er führt das Verhalten des Onkels auf dessen Charakter statt auf seine Umstände zurück; so stempelt er ihn zu schnell als unbelehrbar ab."],"correctIndex":2,"explanation":"Der Kollege versteht den Onkel gedanklich sehr gut, aber dieses Verstehen bleibt ohne Wärme und ohne den Wunsch zu helfen. Der Onkel spürt das: Er fühlt sich analysiert statt ernst genommen. Das Problem ist also nicht zu wenig Verständnis, sondern zu wenig Fürsorge. Wer nur versteht, kann sein Gegenüber im schlimmsten Fall zum Untersuchungsobjekt machen oder sich überlegen fühlen. Wer dagegen zu stark mitleidet, wird von den fremden Gefühlen überschwemmt und zieht sich irgendwann erschöpft zurück; dafür gibt es hier aber keinen Hinweis, denn der Kollege fühlt ja gerade wenig. Ein Gespräch kommt in Gang, wenn zum Verstehen die Sorge um den anderen dazukommt, ohne dessen Panik zu übernehmen. Ein einseitiges Bild durch Bestätigungsfehler setzte voraus, dass er nur Passendes sammelt, doch davon ist keine Rede. Auch ein vorschnelles Urteil über den Charakter des Onkels steht nicht im Szenario, er versteht ja gerade die Gründe seines Denkens.","coreRule":"⚡ Verstehen ohne Fürsorge wird kalt, Fürsorge ohne Abstand wird Panik.","quote":"","quoteLabel":"","beleg":"Werkstück H.1.6 (Der Kipppunkt; Red Flags: Anzeichen für ein Ungleichgewicht; Szenario 2: Die Kalte Analyse)","status":"entwurf","kurz":"Der Kollege versteht den Onkel gedanklich gut, doch ohne Wärme und ohne den Wunsch zu helfen fühlt der sich analysiert statt ernst genommen. Verstehen allein kann das Gegenüber zum Untersuchungsobjekt machen; es braucht die Sorge um den anderen dazu.","prueffrage":"Was sagt der Kollege über sein eigenes Verständnis, und was sagt der Onkel über das Gespräch?","rueckmeldung":[{"option":0,"text":"Wer zu stark mitleidet, kann sich tatsächlich erschöpft zurückziehen. Hier gibt es dafür aber keinen Hinweis: Der Kollege fühlt eher wenig, der Onkel nennt ihn ja gerade „kalt“."},{"option":1,"text":"Einseitiges Belegesammeln würde ein verzerrtes Bild vom Onkel erklären. Davon steht aber nichts im Szenario: Der Kollege kann jeden Schritt nachvollziehen. Das Problem liegt in der fehlenden Wärme, nicht im Bild vom Onkel."},{"option":3,"text":"Ein vorschnelles Urteil über den Charakter wäre ein verbreiteter Fehler, hier wird er aber nicht beschrieben. Der Kollege versteht die Gründe des Onkels sogar genau. Kritisiert wird, wie er diesem begegnet, nicht, wie er ihn einordnet."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Klimecki, Leiberg, Ricard & Singer (2014): Differential Pattern of Functional Brain Plasticity After Compassion and Empathy Training. Social Cognitive and Affective Neuroscience 9(6)","oeffentlich":true,"doi":"10.1093/scan/nst060","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4040103/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Singer & Klimecki (2014): Empathy and Compassion. Current Biology 24(18), R875–R878 (Verlagsseite hier nicht geöffnet; Register b2a0fd0f299 am Volltext bestätigt)","oeffentlich":false,"doi":"10.1016/j.cub.2014.06.054"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"7e2ad356ba5e2231"}},{"id":"qx-h-032","clusterId":"H","werkstueckRef":"H.1.6","stufe":4,"question":"Eine Kollegin sagt: „Mitleiden und Mitgefühl sind im Gehirn im Grunde dasselbe.“ Welche Beobachtung widerspricht dieser Behauptung am stärksten?","options":["Nach dem Mitempfinden-Training ist vor allem das Schmerz- und Negativsystem aktiver, nach dem Fürsorge-Training vor allem das Belohnungs- und Zugehörigkeitssystem.","Nach dem Mitempfinden-Training sind mehrere Areale zugleich aktiver, nach dem Fürsorge-Training ebenfalls, und die Stärke schwankt je nach Person erheblich.","Nach dem Mitempfinden-Training sind vor allem dieselben Areale aktiver wie nach dem Fürsorge-Training, dort jedoch insgesamt etwas stärker.","Nach dem Mitempfinden-Training berichten die Teilnehmer mehr negative Gefühle, nach dem Fürsorge-Training mehr positive, die gemessene Hirnaktivität gleicht sich aber."],"correctIndex":0,"explanation":"Die Behauptung setzt Mitleiden und Mitgefühl gleich. Am stärksten widerspricht ihr ein Befund, in dem beide Trainings jeweils ein anderes Hirnsystem ansprechen. Genau das zeigten Trainingsstudien von Klimecki und Kollegen (2014): Nach dem Empathie-Training waren Insula und anteriorer cingulärer Cortex aktiver (Schmerz, negativer Affekt), nach dem Mitgefühls-Training ventrales Striatum und medialer orbitofrontaler Cortex (Belohnung, Zugehörigkeit). Die Begriffe folgen der Arbeitsgruppe um Singer und Klimecki; andere Autoren teilen anders ein. Dieselben Areale, nur mal stärker, mal schwächer, widersprechen der Gleichsetzung nicht. Dass viele Areale zugleich arbeiten und die Stärke je Person schwankt, sagt nichts darüber, ob beide Trainings dasselbe System nutzen. Auch unterschiedliche Gefühlsberichte bei gleicher Hirnaktivität erschüttern die Gleichsetzung nicht, denn die Behauptung betrifft das Gehirn.","coreRule":"⚡ Wenn zwei Dinge angeblich dasselbe sind, prüfe, ob sie sich unter Test unterschiedlich verhalten: Mitleiden und Mitgefühl lassen sich im Gehirn unterscheiden.","beleg":"Werkstück H.1.6 (Kontext & Tiefe); Fn. gl-h-empathie (Singer/Klimecki 2014, Current Biology 24(18), S. R875–R878; Klimecki u. a. 2014, SCAN 9(6), S. 873–879)","status":"entwurf","scenario":"In einer Trainingsstudie übt eine Gruppe zunächst, die Gefühle anderer mitzuempfinden, und anschließend, sich fürsorglich um andere zu sorgen. Dabei wird die Hirnaktivität gemessen.","kurz":"Der stärkste Widerspruch wäre, dass beide Trainings jeweils ein anderes Hirnsystem ansprechen. Dieselben Areale mit anderer Stärke oder bloß andere Gefühlsberichte reichen nicht, denn die Behauptung betrifft das Gehirn und setzt beides gleich.","prueffrage":"Was genau behauptet die Kollegin über das Gehirn, und welches Messergebnis wäre mit ihrer Behauptung noch vereinbar?","rueckmeldung":[{"option":1,"text":"Dass mehrere Areale zugleich aktiver sind und die Stärke je Person schwankt, wirkt nach einem Befund. Es sagt aber nichts darüber, ob beide Trainings dasselbe System nutzen, und widerspricht der Gleichsetzung deshalb nicht."},{"option":2,"text":"Ein Stärkeunterschied ist zwar ein Unterschied, betrifft aber nur das Ausmaß. Aktivieren beide Trainings vor allem dieselben Areale, spricht das eher für die Gleichsetzung als gegen sie."},{"option":3,"text":"Unterschiedliche Gefühlsberichte sind ein echter Unterschied, aber auf der Ebene des Erlebens. Die Behauptung betrifft das Gehirn, und dort gleicht sich die Aktivität laut dieser Antwort. Das stützt sie eher, als dass es ihr widerspricht."}],"familie":"widerlegung-benennen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Klimecki, Leiberg, Ricard & Singer (2014): Differential Pattern of Functional Brain Plasticity After Compassion and Empathy Training. Social Cognitive and Affective Neuroscience 9(6)","oeffentlich":true,"doi":"10.1093/scan/nst060","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4040103/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Singer & Klimecki (2014): Empathy and Compassion. Current Biology 24(18), R875–R878 (Verlagsseite hier nicht geöffnet; Register b2a0fd0f299 am Volltext bestätigt)","oeffentlich":false,"doi":"10.1016/j.cub.2014.06.054"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"387b7ea27ebbafe3"}},{"id":"qx-h-033","clusterId":"H","werkstueckRef":"H.2.1","stufe":1,"question":"Welche Reaktion ist in diesem Moment am sinnvollsten und warum?","options":["„Das klingt, als würdest du dich von Leuten wie mir nicht ernst genommen fühlen. Habe ich das richtig verstanden?“","„Lass uns zusammen nachschlagen, was Studien dazu sagen. Dann sehen wir beide, wer von uns recht hat.“","„Moment, ‚alle‘ ist ein großes Wort. Das nennt man Verallgemeinerung, und die lasse ich so nicht stehen.“","„Okay, da hast du vielleicht recht. Lass uns einfach das Thema wechseln, damit der Abend ruhig bleibt.“"],"correctIndex":0,"explanation":"In einem eskalierten Gespräch hat das emotionale System 1 die Kontrolle, und System 2 arbeitet nur noch als dessen Anwalt. Ein Fakten-Argument kommt in diesem Zustand kaum an und nährt eher den Streit. Wer stattdessen das Gefühl aufgreift, ohne der Behauptung zuzustimmen, nimmt dem Gegenüber das Bedürfnis, lauter zu werden, und öffnet eine Tür für ein echtes Gespräch. Gemeinsames Nachschlagen klingt kooperativ, macht das Gespräch aber zum Wettstreit um das Rechthaben. Eine Verallgemeinerung zu benennen ist ein anerkanntes Denkwerkzeug, trifft hier aber auf einen Menschen, der sich gerade nicht ernst genommen fühlt, und wirkt wie ein Angriff. Das bloße Zustimmen und Themawechseln gibt die eigene Position auf, nur um Ruhe zu haben. Ein hitziger Moment verlangt, das Gespräch zu retten, statt Recht zu haben.","coreRule":"⚡ Im Feuer erst das Gefühl aufgreifen, nicht den Inhalt bestätigen und nicht mit Fakten kontern.","quote":"","quoteLabel":"","beleg":"Werkstück H.2.1 (Die Taktische Matrix: vier Kern-Techniken; Kontext & Tiefe)","status":"entwurf","scenario":"Bei einer Familienfeier sagt dein Onkel laut: „Ihr Studierten seid doch alle gleich! Ihr sitzt in eurer arroganten Blase und habt keine Ahnung vom echten Leben!“ Du merkst, wie dein Puls steigt und du am liebsten sofort mit Fakten kontern würdest.","kurz":"Wer das Gefühl hinter dem Vorwurf aufgreift, ohne ihm zuzustimmen, entzieht dem Streit den Treibstoff. Fakten oder Gegenvorwürfe erreichen jemanden im Ärger kaum und machen das Gespräch zum Wettstreit ums Rechthaben.","prueffrage":"Was verrät der Ton deines Onkels über seinen Zustand, und wie viel Offenheit für Zahlen ist da gerade zu erwarten?","rueckmeldung":[{"option":1,"text":"Gemeinsam nachzuschlagen klingt fair und Studien sind gute Belege. Gerade das Wort „recht“ macht aus der Situation aber einen Wettstreit, und der verletzte Ärger hinter dem Vorwurf bleibt unbeachtet."},{"option":2,"text":"Die Verallgemeinerung zu erkennen ist inhaltlich richtig, „alle“ trägt hier nicht. Ausgerechnet jemandem, der sich nicht ernst genommen fühlt, wirkt das Benennen aber wie ein Angriff und verschärft den Streit."},{"option":3,"text":"Ruhe zu wollen ist verständlich. Mit dem Zugeständnis bestätigst du aber eine Pauschalaussage, die nicht stimmt, und gibst deine Sicht auf, nur um Streit zu vermeiden. Das Gespräch wird dadurch nicht gerettet, sondern abgebrochen."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, Cook, Ecker u. a. (2020): The Debunking Handbook 2020 (doi 10.17910/b7.1182; geöffnet als PDF bei Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/DebunkingHandbook2020.pdf","seite":"9","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"06b9c9d250d0ae08"}},{"id":"qx-h-034","clusterId":"H","werkstueckRef":"H.2.1","stufe":2,"question":"Welche Antwort ist am ehesten geeignet, die Lage zu beruhigen und das Gespräch zu retten, ohne dem Vorwurf zuzustimmen?","scenario":"In einer hitzigen Diskussion ruft dein Gegenüber laut: „Ihr Wissenschaftsgläubigen seid doch alle gleich! Ihr steckt in eurer arroganten Blase und habt keine Ahnung vom echten Leben!“ Du merkst, wie sich dein eigener Puls beschleunigt.","options":["„Du hast völlig recht: Wir Wissenschaftsgläubigen sind arrogant. Lass uns das Thema einfach fallen lassen, bevor es noch unangenehmer wird.“","„Wenn du jetzt pauschal alle über einen Kamm scherst, ist das kein Argument. Ich gehe auf Beleidigungen nicht ein und antworte erst wieder sachlich.“","„Es klingt, als wärst du frustriert und hättest das Gefühl, dass Leute wie ich auf dich herabschauen. Habe ich das richtig verstanden?“","„Ich verstehe deine Wut, aber sie kommt nur daher, dass du die Studienlage nicht kennst. Hier sind die wichtigsten Zahlen dazu.“"],"correctIndex":2,"explanation":"In einem eskalierten Gespräch bestimmen Gefühle und schnelle, intuitive Reaktionen das Geschehen, und Argumente kommen kaum noch an. Wer den Köder ignoriert und stattdessen das dahinterliegende Gefühl benennt, nimmt dem Streit Energie und öffnet eine kleine Tür zum Gespräch. Die richtige Antwort tut genau das und fragt nach, statt zu urteilen. Die Zustimmung zum Vorwurf ist keine Deeskalation, sondern Unterwerfung: Du stimmst einer Aussage zu, die du selbst nicht teilst; ein Gefühl zu validieren ist nicht dasselbe wie den Inhalt zu validieren. Der Hinweis auf „Beleidigungen“ ist ein Gegenvorwurf und verschiebt den Streit auf die Frage, wer sich falsch verhält. Die Antwort mit „Ich verstehe deine Wut, aber …“ behauptet, das Gegenüber kenne die Studienlage nicht, und wirft ein Fakten-Argument ins Feuer, das kaum ankommt und den Streit eher nährt.","coreRule":"⚡ Antworte auf das Gefühl, nicht auf den Köder.","beleg":"Werkstück H.2.1 (Die Geschichte, Reaktion B; Technik 1: Gefühle validieren; Der Kipppunkt: Deeskalation ist keine Unterwerfung; Kontext & Tiefe: Fakten-Argument im Feuer)","status":"entwurf","kurz":"Im Streit ist das Gegenüber emotional aufgewühlt und Argumente kommen kaum an. Wer das Gefühl hinter dem Vorwurf benennt und nachfragt, nimmt dem Streit Energie, ohne dem Inhalt zuzustimmen oder zurückzuschlagen.","prueffrage":"Wie laut und wie sachlich spricht dein Gegenüber gerade, und wie viel von dem, was du sagst, kommt in diesem Zustand bei ihm an?","rueckmeldung":[{"option":0,"text":"Nachzugeben beendet den Streit schnell und fühlt sich nach Frieden an. Du stimmst aber einer Aussage zu, die du selbst nicht teilst. Das ist Unterwerfung: Ein Gefühl ernst zu nehmen heißt nicht, den Inhalt zu bestätigen."},{"option":1,"text":"Die pauschale Zuschreibung ist wirklich kein Argument, und Grenzen zu setzen ist legitim. Der Satz klingt aber nach Gegenvorwurf und kündigt Rückzug an. So geht es bald darum, wer sich falsch verhält, und das Gefühl dahinter bleibt unbeachtet."},{"option":3,"text":"Sachlich zu bleiben und Zahlen zu nennen wirkt vernünftig. Doch das „aber“ entwertet das Verständnis, die Unterstellung, er kenne die Studienlage nicht, ist ein neuer Vorwurf, und Zahlen kommen in so einer Lage kaum an."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, Cook, Ecker u. a. (2020): The Debunking Handbook 2020 (doi 10.17910/b7.1182; geöffnet als PDF bei Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/DebunkingHandbook2020.pdf","seite":"9","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"5ed412c5560bad2d"}},{"id":"qx-h-035","clusterId":"H","werkstueckRef":"H.2.1","stufe":2,"question":"Dein Onkel hat beim Familienfest gerade behauptet, die Impfstudien seien alle gekauft. Du willst widersprechen, ohne dass er sofort in die Verteidigung geht. Welche Formulierung beschreibt deine eigene Wahrnehmung, statt ihm etwas zuzuschreiben?","options":["„Mich beunruhigt, dass du den Studien so wenig traust. Du lässt dich offenbar von Misstrauen leiten.“","„Unabhängige Fachleute prüfen solche Studien mehrfach. Die Ergebnisse sind in der Fachwelt breit anerkannt.“","„Ich habe den Eindruck, dass du dich nicht gründlich informiert hast. Du bleibst lieber bei deiner Meinung.“","„Die Studien, die ich bisher gesehen habe, deuten für mich in eine andere Richtung. Das verwirrt mich.“"],"correctIndex":3,"explanation":"Eine Aussage, die deine eigene Wahrnehmung beschreibt, ist eine persönliche Zustandsbeschreibung: Sie ist unangreifbar und lädt zur Klärung ein. Wer dem anderen dagegen eine Eigenschaft zuschreibt, erhebt eine Anklage, auch wenn ein „ich“ oder ein Gefühl im Satz steht („Ich habe den Eindruck, dass du dich nicht gründlich informiert hast“; „Mich beunruhigt, dass du den Studien so wenig traust“). Solche Anklagen zwingen das Gegenüber in eine Verteidigungshaltung. Der Verweis auf Fachleute ist sachlich zutreffend, beschreibt aber nicht dein eigenes Erleben, sondern stellt eine Autorität gegen den Onkel und lädt zur Gegenwehr ein. Eskaliert ein Gespräch, geht es nur noch um Gewinnen und Verlieren. Eine Aussage über dein eigenes Erleben dagegen greift ihn nicht an.","coreRule":"⚡ Prüfe nicht, ob „ich“ im Satz steht, sondern ob du beschreibst, was bei dir ankommt, oder sagst, was der andere ist.","beleg":"Werkstück H.2.1 (Die Taktische Matrix: Technik 2, „Ich“-Botschaften)","status":"entwurf","scenario":"Beim Familienfest wird die Stimmung hitzig. Dein Onkel sagt laut: „Die Impfstudien sind doch alle von der Industrie gekauft!“ Du willst dagegenhalten, aber das Gespräch nicht noch weiter anheizen.","kurz":"Wer beschreibt, was er selbst wahrnimmt, macht eine Aussage, die niemand widerlegen kann und die zur Klärung einlädt. Ein „ich“ im Satz reicht nicht: Eine Zuschreibung wie „du vertraust nicht“ bleibt eine Anklage und ruft Verteidigung hervor.","prueffrage":"Worüber sagt der Satz etwas aus: über das, was du erlebst, oder über die Person, der du antwortest?","rueckmeldung":[{"option":0,"text":"Ein Gefühl am Satzanfang lässt ihn nach einer Ich-Botschaft klingen. Doch „Du lässt dich von Misstrauen leiten“ ist eine Zuschreibung an ihn, also eine Anklage, auf die er sich verteidigen wird."},{"option":1,"text":"Der Hinweis auf unabhängige Prüfung ist sachlich zutreffend. Er beschreibt aber nicht, was du selbst wahrnimmst, sondern stellt eine Autorität gegen deinen Onkel. Das lädt eher zur Gegenwehr ein als zur Klärung."},{"option":2,"text":"„Ich habe den Eindruck“ klingt nach eigener Sicht, doch gesagt wird, er habe sich nicht gründlich informiert und hänge an seiner Meinung. Das ist eine Eigenschaft, die du ihm zuschreibst, und er wird sich dagegen wehren."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Rogers, Howieson & Neame (2018): I understand you feel that way, but I feel this way: the benefits of I-language and communicating perspective during conflict. PeerJ 6:e4831","oeffentlich":true,"doi":"10.7717/peerj.4831","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5961625/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"6e58a88958c2835b"}},{"id":"qx-h-036","clusterId":"H","werkstueckRef":"H.2.1","stufe":3,"question":"Welche der vier Reaktionen sorgt zwar für Ruhe, gibt dafür aber eine falsche Behauptung preis?","scenario":"Dein Onkel behauptet am Familientisch, Echsenmenschen kontrollierten die Regierung, und wird dabei immer lauter. Du willst verhindern, dass der Abend eskaliert.","options":["„Ich merke, wie sehr dich das Thema beschäftigt. Inhaltlich sehe ich es anders, aber ich höre dir zu.“","„Na gut, vielleicht ist da was dran. Hauptsache, wir haben heute Abend Frieden.“","„Ich merke, wir drehen uns im Kreis. Lass uns morgen mit frischem Kopf weiterreden; mir ist das Gespräch wichtig.“","„Uns beiden liegt das Wohl der Familie am Herzen. Über den Weg dorthin denken wir nur unterschiedlich.“"],"correctIndex":1,"explanation":"Beruhigen und zustimmen sind zwei verschiedene Dinge. Du kannst das Gefühl deines Gegenübers anerkennen, eine Pause vorschlagen oder eine gemeinsame Absicht benennen, ohne dabei die Sachbehauptung gelten zu lassen. Dein Onkel erfährt in diesen Fällen: Ich nehme dich ernst, aber ich teile deine Aussage nicht. „Vielleicht ist da was dran“ dagegen signalisiert Zustimmung zu einer unbelegten Behauptung, nur um Ruhe zu haben. Der Frieden wird damit mit einer Unwahrheit erkauft, und der Onkel fühlt sich in seiner Überzeugung bestätigt. Deeskalieren soll das Gespräch offenhalten, nicht die eigene Position aufgeben.","coreRule":"⚡ Gefühle darfst du bestätigen, falsche Behauptungen nicht.","beleg":"Werkstück H.2.1 (Der Kipppunkt; Die Taktische Matrix)","status":"entwurf","kurz":"Beruhigen heißt nicht zustimmen: „Vielleicht ist da was dran“ erkauft den Frieden mit einer Unwahrheit und bestärkt den Onkel. Gefühl anerkennen, Pause vorschlagen oder Gemeinsames betonen beruhigt ebenfalls, lässt die Behauptung aber nicht gelten.","prueffrage":"Was erfährt dein Onkel über deine Sicht auf seine Behauptung, wenn er nur deine Antwort hört?","rueckmeldung":[{"option":0,"text":"Hier bleibt die Ruhe nicht auf Kosten der Wahrheit: Du erkennst sein Gefühl an und sagst offen, dass du es inhaltlich anders siehst. Deine Position gibst du damit nicht auf."},{"option":2,"text":"Eine Pause vorzuschlagen wirkt vielleicht wie Ausweichen, ist aber echte Deeskalation: Du stimmst der Behauptung nicht zu und sagst dem Onkel zugleich, dass dir das Gespräch wichtig ist. Das Thema bleibt offen."},{"option":3,"text":"Die gemeinsame Absicht zu betonen, beruhigt, ohne der Sachbehauptung zuzustimmen. Der Satz räumt ausdrücklich ein, dass ihr unterschiedlich denkt. Du gibst also nichts preis, was du nicht preisgeben willst."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ea6bcce04bde3c5f"}},{"id":"qx-h-037","clusterId":"H","werkstueckRef":"H.2.2","stufe":1,"question":"Du sprichst mit einer Kollegin, die fest überzeugt ist, dass ihr Wundermittel gegen Migräne hilft. Du willst herausfinden, wie sie zu dieser Überzeugung gekommen ist, ohne sie anzugreifen. Welche Frage hilft dir, ihre Überzeugung genauer zu fassen und die Methode dahinter zu klären?","options":["„Wie sicher bist du auf einer Skala von 0 bis 100, und was ist der Hauptgrund für diese Einschätzung?“","„Seit wie vielen Jahren hast du schon Migräne, und wie oft kommen die Anfälle im Monat?“","„Welche Nebenwirkungen kennst du von dem Mittel, und was steht dazu im Beipackzettel?“","„Wie belasten dich die Anfälle im Arbeitsalltag, und was belastet dich daran am meisten?“"],"correctIndex":0,"explanation":"„Absolut sicher“ ist ein Entweder-oder, über das sich schlecht reden lässt. Eine Skala von 0 bis 100 macht daraus ein flexibles Spektrum, an dem man gemeinsam ansetzen kann: Warum 95 und nicht 60? Die anschließende Frage nach dem Hauptgrund deckt die Methode auf, auf der die Sicherheit beruht (zum Beispiel eigene Erfahrung oder ein Tipp einer Freundin). Genau diese Methode lässt sich dann auf ihre Verlässlichkeit prüfen, ohne dass du die Schlussfolgerung angreifst. Die Frage nach Dauer und Häufigkeit der Anfälle zeigt Anteilnahme, klärt aber nicht, worauf ihre Sicherheit beruht. Nebenwirkungen und Beipackzettel sind ein sinnvolles Thema, doch hier geht es um ihre Überzeugung, nicht um das Mittel. Wie die Anfälle den Arbeitsalltag belasten, rückt die Person in den Blick, nicht aber den Weg zu ihrer Überzeugung.","coreRule":"⚡ Frag erst nach dem Grad der Sicherheit, dann nach dem Grund dafür, nicht nach dem Urteil.","beleg":"Werkstück H.2.2 (Kontext & Tiefe: Schritte 3 und 4, 6)","status":"entwurf","scenario":"Deine Kollegin sagt: „Ich bin mir absolut sicher, dass dieses Mittel gegen Migräne hilft.“ Du möchtest weder streiten noch sofort Studien auf den Tisch legen, sondern verstehen, worauf ihre Sicherheit beruht.","kurz":"Eine Skala macht aus „absolut sicher“ ein Spektrum, an dem ihr gemeinsam ansetzen könnt, und der Hauptgrund zeigt, worauf ihre Sicherheit beruht. Diese Methode lässt sich prüfen, ohne dass du ihre Schlussfolgerung angreifst.","prueffrage":"Was hat deine Kollegin bisher tatsächlich gesagt: Nennt sie einen Grund für ihre Sicherheit oder nur die Sicherheit selbst?","rueckmeldung":[{"option":1,"text":"Dauer und Häufigkeit der Anfälle zeigen Anteilnahme und geben dir Hintergrund zu ihrer Lage. Sie sagen aber nichts darüber, worauf ihre Sicherheit beruht, also auch nicht, nach welcher Methode sie zu ihrer Überzeugung gekommen ist."},{"option":2,"text":"Nebenwirkungen und Beipackzettel sind durchaus ein sinnvolles Thema. Hier geht es aber um ihre Überzeugung und nicht um das Mittel selbst, und der Weg dorthin kommt bei dieser Frage nicht zur Sprache."},{"option":3,"text":"Die Frage nach der Belastung im Arbeitsalltag ist einfühlsam und rückt sie als Person in den Blick. Wie sie zu ihrer Überzeugung gekommen ist, bleibt dabei jedoch offen."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Street Epistemology International: Using a Confidence Scale in Street Epistemology (31.05.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m08-using-a-confidence-scale-in-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Street Epistemology International: What Is Street Epistemology? A Beginner's Introduction (12.04.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m01-what-is-street-epistemology","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"8e4e9f6b7c855527"}},{"id":"qx-h-038","clusterId":"H","werkstueckRef":"H.2.2","stufe":2,"question":"Welche Anschlussfrage ist dafür am besten geeignet?","scenario":"Ein Kollege ist zu 95 Prozent sicher, dass Rosenquarz Kopfschmerzen heilt. Seine Begründung: Eine Freundin hat es empfohlen, und bei ihm selbst hörten die Beschwerden danach auf. Du möchtest mit ihm ins Gespräch kommen, ohne dass er sich angegriffen fühlt, und ihm helfen, die Verlässlichkeit seiner Begründung selbst zu prüfen.","options":["„Du hast also öfter Kopfschmerzen. Wie lange geht das schon so? Und hast du schon mit einer Ärztin darüber gesprochen?“","„Du hast den Rosenquarz also ausprobiert. Woher hast du ihn, und wie hast du ihn benutzt? Wie oft hast du ihn bei dir getragen?“","„Du bist also fest überzeugt. Würdest du Freunden mit Kopfschmerzen raten, es zu versuchen? Was würdest du ihnen dazu sagen?“","„Du verlässt dich also auf deine Erfahrung. Wie ließe sich prüfen, ob wirklich der Kristall geholfen hat? Welcher Weg wäre am verlässlichsten?“"],"correctIndex":3,"explanation":"Wer die Überzeugung eines Menschen direkt angreift, löst meist Abwehr aus, und mit Abwehr endet das Nachdenken. Besser ist es, zuerst zu verstehen, worauf sich die Sicherheit stützt, und dann gemeinsam zu prüfen, ob dieser Weg verlässlich ist. Hier ist die Begründung eine einzelne Erfahrung: Die Kopfschmerzen hörten nach dem Kristall auf. Das passt aber ebenso zum Placebo-Effekt oder dazu, dass sie von allein vergangen wären. Die Frage, wie man das auseinanderhalten könnte, lädt zum Mitdenken ein, ohne ein Urteil zu fällen. Fragen nach der Krankengeschichte, nach Herkunft und Gebrauch des Steins oder nach einem Rat an Freunde zeigen Interesse, klären aber nicht, ob seine Erfahrung als Begründung trägt. Sie lassen offen, ob der Stein oder etwas anderes die Beschwerden beendet hat.","coreRule":"⚡ Frag nach dem Weg zur Überzeugung und lade zum gemeinsamen Prüfen ein, statt das Ergebnis anzugreifen.","beleg":"Werkstück H.2.2 (Die Geschichte, Ansatz B; Kontext & Tiefe: Schritt 5; Red Flags)","status":"entwurf","kurz":"Wer fragt, wie sich prüfen ließe, ob wirklich der Kristall geholfen hat, lädt zum Mitdenken ein, ohne zu urteilen. Eine einzelne Erfahrung passt ebenso zum Placebo-Effekt oder zu Beschwerden, die von allein vergingen.","prueffrage":"Worauf stützt dein Kollege seine 95 Prozent, und welche Anschlussfrage knüpft an genau diese Stütze an?","rueckmeldung":[{"option":0,"text":"Die Frage zeigt echtes Interesse und greift nichts an. Sie führt aber zu seiner Krankengeschichte, nicht zu seiner Begründung, und lässt offen, ob seine Erfahrung als Beleg trägt."},{"option":1,"text":"Herkunft und Gebrauch des Steins zu erfragen, wirkt offen und respektvoll. Selbst mit allen Details wäre aber noch nicht geklärt, ob der Stein oder etwas anderes die Beschwerden beendet hat."},{"option":2,"text":"Die Frage ist freundlich und lässt ihn erzählen. Sein Rat an Freunde würde aber auf derselben einzelnen Erfahrung beruhen und könnte die Sicherheit sogar festigen. Ob die Erfahrung trägt, bleibt ungeprüft."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Street Epistemology International: What Is Street Epistemology? A Beginner's Introduction (12.04.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m01-what-is-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook (Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Boghossian, P. (2013): A Manual for Creating Atheists. Pitchstone Publishing (Begriffsprägung; Register b7b36492df7, sekundär bestätigt)","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"c7265f77e485f9e1"}},{"id":"qx-h-039","clusterId":"H","werkstueckRef":"H.2.2","stufe":3,"question":"Wobei bringt dir eine Reihe offener Fragen zur Methode deines Gegenübers am wenigsten?","options":["Jemand behauptet, Paris sei die Hauptstadt von Deutschland, und beruft sich dabei auf eine vage Erinnerung an eine Schulstunde vor vielen Jahren.","Jemand ist zu 90 Prozent sicher, dass seine Intuition ihm den richtigen Beruf zeigt, und bleibt trotz eigener Zweifel bei dieser Überzeugung.","Jemand hält Horoskope für absolut zutreffend und erzählt dir ausführlich, wie sehr ihm das im Leben hilft und wie sicher er sich ist.","Jemand hat vor Kurzem in einer Gruppe ein Weltbild übernommen und verteidigt es mit viel Gefühl und mit nur wenigen echten Belegen."],"correctIndex":0,"explanation":"Fragen nach der Methode lohnen sich bei tiefen, identitätsstiftenden Überzeugungen: Hier steht die Zuverlässigkeit des Wegs zur Überzeugung im Mittelpunkt, und genau das lässt sich gemeinsam erkunden. Bei einer reinen Tatsachenfrage wie der nach der Hauptstadt Deutschlands ist eine sokratische Befragung dagegen meist überflüssig; hier genügt eine einfache Richtigstellung.","coreRule":"⚡ Faktenfragen beantwortest du, Überzeugungen erkundest du.","beleg":"Werkstück H.2.2 (Red Flags: Wann man SE nicht anwenden sollte)","status":"entwurf","scenario":"Du sprichst mit vier Menschen, die jeweils etwas behaupten.","quote":"","quoteLabel":"","kurz":"Offene Fragen zur Methode lohnen sich, wo der Weg zur Überzeugung selbst zählt. Bei einer schlichten Tatsache wie der Hauptstadt Deutschlands sind sie meist überflüssig, hier genügt eine Richtigstellung. Nicht jede Behauptung ist eine Weltanschauung.","prueffrage":"Wie viel hängt für jeden der vier Menschen an seiner Behauptung, und was ginge ihm verloren, wenn er sich irrte?","rueckmeldung":[{"option":1,"text":"Hier lohnen sich offene Fragen gerade: Wie verlässlich ist Intuition als Weg zur Berufswahl, und woher kommen die Zweifel? Daran lässt sich gemeinsam arbeiten, anders als bei einer einfach nachprüfbaren Tatsache."},{"option":2,"text":"Auch beim Horoskop lohnt die Frage nach dem Weg zur Überzeugung: Woran würde die Person merken, dass es nicht zutrifft? Wie jemand zu so einer Gewissheit kommt, bietet genug Stoff für ein offenes Gespräch."},{"option":3,"text":"Ein Weltbild mit viel Gefühl und wenig Belegen ist genau der Fall, in dem Fragen nach Herkunft und Prüfbarkeit weiterhelfen. Behutsam gestellt, öffnen sie das Gespräch, statt es zu verengen."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Street Epistemology International: What Is Street Epistemology? A Beginner's Introduction (12.04.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m01-what-is-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, Cook, Ecker u. a. (2020): The Debunking Handbook 2020 (doi 10.17910/b7.1182; geöffnet als PDF bei Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/DebunkingHandbook2020.pdf","seite":"9","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"32b54c33e6296c61"}},{"id":"qx-h-040","clusterId":"H","werkstueckRef":"H.2.2","stufe":4,"question":"Welche Frage bringt ihn am ehesten dazu, selbst zu prüfen, wie belastbar seine Überzeugung ist?","scenario":"Ein Kollege sagt dir im Gespräch: „Ich bin zu 95 % sicher, dass Heilkristalle Krankheiten heilen. Meine Kopfschmerzen sind verschwunden, als ich einen Rosenquarz benutzt habe, und eine Freundin schwört auch darauf.“ Du willst ihn nicht belehren, sondern ihn zum Nachdenken über seine eigene Überzeugung bringen, ohne dass er sich angegriffen fühlt.","options":["„Was meinst du genau mit ‚Krankheiten heilen‘, und welche gehören für dich dazu?“","„Wie bist du zu dieser Überzeugung gekommen, und wie verlässlich ist dieser Weg?“","„Wo hast du den Rosenquarz gekauft, und wie wendest du ihn bei Kopfschmerzen an?“","„Wie fühlst du dich, wenn die Kopfschmerzen kommen, und was belastet dich daran am meisten?“"],"correctIndex":1,"explanation":"Wer eine tief gehaltene Überzeugung frontal widerlegt, macht sein Gegenüber defensiv, und das Gespräch endet. Wirksamer ist es, nicht die Schlussfolgerung („Kristalle heilen nicht“) anzugreifen, sondern das Verfahren zu untersuchen, mit dem die Person dorthin gekommen ist: Worauf stützt sich die Sicherheit, und kann dieser Weg auch zu falschen Ergebnissen führen? Hier ist der Weg die persönliche Erfahrung („Kopfschmerzen sind verschwunden“). Ob sie verlässlich ist, lässt sich gemeinsam fragen: Wäre der Schmerz vielleicht auch von allein vergangen, oder spielt der Placebo-Effekt eine Rolle? Die Frage, was „Krankheiten heilen“ genau heißen soll, schärft die Aussage, prüft aber nicht den Weg zu ihr. Fragen nach Kauf und Anwendung des Steins bleiben beim Gegenstand, nicht bei der Überzeugung. Die Frage nach der Belastung durch die Kopfschmerzen zeigt Anteilnahme, führt aber nicht zur Prüfung seiner Begründung.","coreRule":"⚡ Frag nach der Methode, nicht nach der Schlussfolgerung.","beleg":"Werkstück H.2.2 (Street Epistemology); Fn. gl-h-4 (Boghossian 2013, A Manual for Creating Atheists)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wer fragt, wie jemand zu seiner Überzeugung kam und wie verlässlich dieser Weg ist, lässt ihn die eigene Begründung prüfen, ohne die Schlussfolgerung anzugreifen. Ein Frontalangriff macht defensiv und beendet das Gespräch.","prueffrage":"Welche Gründe nennt dein Kollege selbst für seine 95 Prozent, und welche davon hat er selbst erlebt?","rueckmeldung":[{"option":0,"text":"Die Frage schärft, was „heilen“ heißen soll, und ist ein fairer Gesprächseinstieg. Sie prüft aber nur die Aussage, nicht den Weg, auf dem er zu seiner Sicherheit kam, und genau dort setzt die Prüfung an."},{"option":2,"text":"Interesse an seinen Erfahrungen wirkt unaufdringlich und hält das Gespräch freundlich. Die Frage bleibt aber beim Stein und seiner Anwendung, nicht bei der Überzeugung dahinter. So kommt er nicht ins Nachdenken über seine Begründung."},{"option":3,"text":"Anteilnahme am Leiden ist menschlich und gut für die Stimmung. Sie führt aber weg von der Überzeugung: Über die Belastung durch die Kopfschmerzen zu sprechen, regt nicht an, die Gründe für seine Sicherheit zu prüfen."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Street Epistemology International: What Is Street Epistemology? A Beginner's Introduction (12.04.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m01-what-is-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Street Epistemology International: Using a Confidence Scale in Street Epistemology (31.05.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m08-using-a-confidence-scale-in-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook (Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"267cc7a85b735581"}},{"id":"qx-h-041","clusterId":"H","werkstueckRef":"H.2.3","stufe":1,"question":"Was ist am Vorgehen von Jonas in diesem Gespräch das Problem?","options":["Jonas hört nur so lange zu, bis er einen Punkt zum Widerlegen gefunden hat. Was Mehmet meint und fühlt, bleibt ungeklärt, und genau das nimmt Mehmet wahr.","Jonas greift Mehmet als Person an, statt auf dessen Aussagen einzugehen. Ein Angriff auf den Menschen ersetzt die Prüfung der Sache, und genau das nimmt Mehmet wahr.","Jonas lenkt auf ein anderes Thema um, bevor Mehmets Anliegen besprochen ist. Die eigentliche Frage nach der Impfung rückt aus dem Blick, und genau das nimmt Mehmet wahr.","Jonas gibt Mehmet vorschnell recht, um Streit zu vermeiden. Seine Zustimmung ist nur Höflichkeit, und er verschweigt damit seine eigentliche Haltung."],"correctIndex":0,"explanation":"Jonas hört nur scheinbar zu: Die Worte laufen durch seine eigene Agenda, während der Kopf schon die Widerlegung baut. Damit bleibt offen, was Mehmet eigentlich sagen will und was ihn antreibt, etwa Sorge oder Misstrauen. Verstehen entsteht eher, wenn man die Aussage in eigenen Worten zurückgibt, Gefühle benennt, offen nachfragt und Ablenkungen wie das Handy weglässt; erst dann lässt sich prüfen, worüber man überhaupt streitet. Die anderen Gedanken beschreiben echte Gesprächsfehler, passen aber nicht auf diese Szene: Jonas sagt nichts über Mehmet als Person, er will dessen Aussagen widerlegen. Er bleibt auch beim Thema Impfung und wechselt nicht zu etwas anderem. Und er stimmt nicht aus Höflichkeit zu, sondern widerspricht sofort.","coreRule":"⚡ Hör zu, um zu verstehen, nicht um zu antworten.","quote":"","quoteLabel":"","beleg":"Werkstück H.2.3 (Kernidee; Kontext & Tiefe; Werkbank-Frage)","status":"entwurf","scenario":"Jonas' Schwager Mehmet erzählt aufgebracht, dass er nach der Impfung seiner Tochter ernste Zweifel an Medizin und Behörden habe. Jonas nickt, schaut aber nebenbei auf sein Handy und überlegt schon, mit welchen Studien er gleich alles widerlegen kann. Als Mehmet Luft holt, setzt Jonas sofort an: „Das ist alles längst widerlegt, und zwar so …“ Mehmet winkt ab und sagt: „Du hörst mir gar nicht zu.“","kurz":"Jonas hört nur zum Schein zu, weil er schon die Widerlegung baut, und erfährt so nie, was Mehmet eigentlich meint und antreibt. Naheliegend ist, ihn dafür zu halten, dass er Mehmet angreift, dabei bleibt er beim Thema.","prueffrage":"Was tut Jonas, während Mehmet spricht, und was tut er, sobald Mehmet Luft holt?","rueckmeldung":[{"option":1,"text":"Ein Angriff auf die Person ist ein echter Gesprächsfehler. Hier aber sagt Jonas nichts über Mehmet selbst: Er will dessen Aussagen mit Studien widerlegen, und das Problem liegt davor, im fehlenden Zuhören."},{"option":2,"text":"Ein Themenwechsel würde Mehmets Anliegen tatsächlich verdrängen. Jonas bleibt aber bei der Impfung und will genau dazu Studien anführen. Ungeklärt bleibt Mehmets Anliegen, weil Jonas nicht zuhört, nicht weil er abschweift."},{"option":3,"text":"Aus Höflichkeit zuzustimmen, ist ein bekannter Fehler. Jonas nickt zwar, widerspricht aber sofort und ausführlich. Das Nicken ist nur Fassade fürs Zuhören und keine Zustimmung, die er später zurücknehmen müsste."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kalla & Broockman (2020): Reducing Exclusionary Attitudes through Interpersonal Conversation: Evidence from Three Field Experiments (APSR 114(2), doi 10.1017/S0003055419000923; frei als SocArXiv-Vorabfassung vom 17.01.2020)","oeffentlich":true,"doi":"10.31235/osf.io/2ra9x","seite":"Abstract (S. 1 der Vorabfassung)","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c697b631c857fc8c"}},{"id":"qx-h-042","clusterId":"H","werkstueckRef":"H.2.3","stufe":2,"question":"Welche deiner möglichen Antworten erreicht das am besten?","scenario":"Dein Freund erzählt dir seit einigen Minuten, wie sehr ihn ein Streit mit seiner Chefin beschäftigt. Er sagt: „Ich habe ihr gestern gesagt, dass ich so nicht weiterarbeiten will, und sie hat nur gesagt, das sei kein guter Zeitpunkt. Ich komme mir vor, als wäre ich ihr egal.“ Du willst, dass er sich verstanden fühlt und dass du selbst sicher bist, ihn richtig verstanden zu haben.","options":["„Das kenne ich: Mein früherer Vorgesetzter hat meine Anliegen auch ständig abgetan, und das hat mich damals lange beschäftigt. Du bist nicht allein damit.“","„An deiner Stelle würde ich ihr in einem ruhigen Moment schreiben, was dir wichtig ist, und ihr Zeit zum Antworten lassen. Dann klärt sich vieles.“","„Vielleicht hat sie es nicht böse gemeint, sondern steht gerade selbst unter Druck. Bestimmt wollte sie dich nicht übergehen, und es renkt sich wieder ein.“","„Wenn ich dich richtig verstehe, ärgert dich vor allem, dass sie dein Anliegen abgetan hat. Du fühlst dich nicht ernst genommen. Stimmt das so?“"],"correctIndex":3,"explanation":"Du willst zwei Dinge erreichen: Er soll sich verstanden fühlen, und du willst wissen, ob dein Bild von seiner Lage stimmt. Das gelingt, wenn du in eigenen Worten wiedergibst, was du gehört hast, und ihm die Chance gibst, dich zu korrigieren. So ist dein Verständnis geprüft, bevor du irgendetwas bewertest oder rätst. Eine eigene Geschichte kann Nähe schaffen, macht aber dich zum Mittelpunkt und prüft nicht, ob du ihn richtig verstanden hast. Ein Ratschlag kann in anderer Lage hilfreich sein, kommt hier aber, bevor klar ist, was ihn beschäftigt. Der Blick in die Lage der Chefin ist ein guter Gedanke für später, klärt jetzt aber weder, wie es ihm geht, noch ob du ihn verstanden hast.","coreRule":"⚡ Gib zurück, was du gehört hast, und frag, ob es stimmt.","beleg":"Werkstück H.2.3 (Technik 1: Paraphrasieren; Red Flags; Werkbank-Frage)","status":"entwurf","kurz":"Wenn du in eigenen Worten wiedergibst, was du gehört hast, und ihm die Korrektur anbietest, fühlt er sich gehört und du prüfst dein Bild. Der naheliegende Fehler: gleich zu trösten, zu raten oder zu deuten, bevor klar ist, was ihn bewegt.","prueffrage":"Was von dem, was der Freund gesagt hat, kannst du wörtlich belegen, und was hast du bisher nur selbst dazugedacht?","rueckmeldung":[{"option":0,"text":"Eine ähnliche Erfahrung kann Nähe schaffen. Hier lenkt sie aber den Blick auf dich und deinen früheren Chef, und ob du seine Lage richtig erfasst hast, bleibt ungeprüft."},{"option":1,"text":"Ein Vorschlag kann in anderer Lage genau richtig sein. Hier kommt er, bevor klar ist, was ihn am meisten beschäftigt, und ob sich danach „vieles klärt“, weiß niemand."},{"option":2,"text":"Den Blick auf die Lage der Chefin kannst du später gut gebrauchen. Jetzt lässt er offen, wie es deinem Freund geht, und ob sie es „nicht böse meinte“, wissen wir nicht. Zudem klingt sein Gefühl nach Kleinreden."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"cc347cab036879cd"}},{"id":"qx-h-043","clusterId":"H","werkstueckRef":"H.2.3","stufe":3,"question":"Was ist jetzt der beste nächste Schritt?","scenario":"Du streitest mit deiner Schwester über die Pflege eurer Mutter. Du bist überzeugt, dass sie sich zu wenig kümmert. Bevor du deinen Standpunkt darlegst, willst du sicherstellen, dass du ihre Sicht wirklich verstanden hast, und fasst sie zusammen: „Du sagst also, dass du dich überfordert fühlst und dir von mir mehr Anerkennung wünschst.“ Sie antwortet: „Na ja, so ungefähr.“","options":["Du gehst davon aus, dass „so ungefähr“ genügt, und erklärst nun deinen eigenen Standpunkt, denn sie hat deine Zusammenfassung nicht zurückgewiesen.","Du fragst nach, was an deiner Zusammenfassung noch nicht stimmt, und fasst ihren Standpunkt neu zusammen, bis sie ihn als zutreffend bestätigt.","Du schlägst vor, das Thema zu vertagen und erst in einer Woche weiterzusprechen, damit sich beide in Ruhe Gedanken machen und die Gemüter abkühlen können.","Du machst einen Vorschlag, wie ihr die Pflege eurer Mutter fair aufteilen könntet, damit das Gespräch zügig zu einer Lösung und zu einer Einigung kommt."],"correctIndex":1,"explanation":"Ein halbherziges „so ungefähr“ ist kein Zeichen, dass du sie verstanden hast. Es zeigt eher, dass noch etwas fehlt oder verzerrt ist. Wer jetzt weiterredet, antwortet auf ein Bild von ihr, das sie selbst nicht teilt, und sie fühlt sich weiter missverstanden. Erst wenn sie deine Zusammenfassung aus eigener Sicht als zutreffend bestätigt, etwa mit „Ja, genau“, weißt du, dass ihre Position richtig bei dir angekommen ist. Dafür musst du ihr nicht zustimmen: Verstehen ist nicht Einverstandensein. Es reicht, ihren Standpunkt so zu fassen, dass sie ihn als ihren erkennt. Das Nachfragen kostet anfangs Zeit, verändert aber die Dynamik des Gesprächs, weil sie spürt, dass du ihre Sicht ernsthaft erfassen willst. Ein Lösungsvorschlag ist ein sinnvoller Schritt, aber erst, wenn beide wissen, worum es dem anderen geht. Eine Pause hilft, wenn die Gemüter überkochen; hier ist offen, ob ihre Sicht richtig angekommen ist, und das klärt ein Aufschub nicht. Den eigenen Standpunkt darfst du später darlegen, nur nicht auf der Grundlage einer unbestätigten Zusammenfassung.","coreRule":"⚡ Erst wenn der andere sagt „Ja, genau“, bist du an der Reihe.","beleg":"Werkstück H.2.3 (Die Schmiede-Übung: Die Papageien-Regel)","status":"entwurf","kurz":"Ein halbherziges „so ungefähr“ zeigt, dass in deiner Zusammenfassung noch etwas fehlt oder verzerrt ist. Erst wenn sie sich darin wiedererkennt, hast du ihre Sicht verstanden, und das geht nur durch Nachfragen und erneutes Zusammenfassen.","prueffrage":"Welche Teile deiner Zusammenfassung hat deine Schwester ausdrücklich aufgegriffen oder bestätigt?","rueckmeldung":[{"option":0,"text":"Sie hat nicht widersprochen, das stimmt. Aber „so ungefähr“ ist keine Bestätigung. Wenn du jetzt dein Anliegen vorträgst, antwortest du auf ein Bild von ihr, das sie selbst nicht teilt."},{"option":2,"text":"Eine Pause tut gut, wenn die Gemüter überkochen. Hier ist aber offen, ob ihre Sicht richtig angekommen ist, und das klärt auch eine Woche Abstand nicht. Die Unklarheit bliebe einfach stehen."},{"option":3,"text":"Ein Vorschlag zur Aufteilung ist ein sinnvoller Schritt, aber ein verfrühter. Solange nicht klar ist, worum es ihr geht, trifft er womöglich ihr eigentliches Anliegen gar nicht."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"76156cc199e20627"}},{"id":"qx-h-044","clusterId":"H","werkstueckRef":"H.2.3","stufe":4,"question":"Welche Antwort setzt aktives Zuhören um, wenn dein Ziel ist, dass das Gespräch mit Alex weitergeht?","scenario":"Alex, ein alter Freund, meldet sich nach Monaten: Er schlafe kaum, analysiere nachts „Drops“ und habe Angst um alle, die „es nicht sehen“. Er schreibt: „Manchmal denke ich, ich werde verrückt. Du hältst mich wahrscheinlich für einen Idioten.“","options":["„Danke, dass du dich meldest. Ich höre, dass du kaum schläfst und Angst hast. Ich halte dich nicht für einen Idioten. Magst du erzählen, was dich nachts am meisten beunruhigt?“","„Danke, dass du dich meldest. Ich sehe, dass du dich in etwas verrennst, und das macht mir Sorgen. Deshalb schicke ich dir gleich drei Faktenchecks, die das widerlegen.“","„Danke, dass du dich meldest. Ich verstehe dich vollkommen und sehe es ähnlich: Vieles läuft im Verborgenen ab. Du bist damit nicht allein, wir ziehen das gemeinsam durch.“","„Danke, dass du dich meldest. Schlafmangel und Angst sind ernst und gehören zu einer Fachperson. Ich bin dafür der Falsche, melde dich bitte bei einer Beratungsstelle.“"],"correctIndex":0,"explanation":"Wer verstehen will, was jemand erlebt, nimmt zuerst auf, was er sagt und fühlt: das Gefühl benennen (Angst, Erschöpfung), das Gehörte in eigenen Worten wiedergeben und offen nachfragen. Das hält die Tür offen und liefert dir die Informationen, die du für jedes weitere Gespräch brauchst. Du musst Alex nicht zustimmen, um ihn zu verstehen. Faktenchecks können später ihren Platz haben, antworten jetzt aber auf den Inhalt und überhören den Menschen. Wer den Inhalt bestätigt, ohne ihn verstanden oder geprüft zu haben, verwechselt Mitgefühl mit Zustimmung. Fachliche Hilfe kann sinnvoll sein, doch wer Alex sofort weiterreicht, hat ihm noch nicht zugehört, und das Gespräch endet, bevor es begonnen hat.","coreRule":"⚡ Biete Verbindung an, keine Korrektur: Hör zu, um zu verstehen, nicht um zu antworten.","beleg":"Werkstück H.2.3 (Techniken: Paraphrasieren, Emotionen benennen, klärende Fragen); Fn. gl-h-zuhoeren (Braun/Burian/Diefenbacher 2016; Wilke 1994; Kraft 2016). Buchbezug „im Sinne von H.2.3“ aus der Frage entfernt; Optionen auf gleiche Bauart und ähnliche Länge angeglichen (Option 3 hat kein Begründungsanhängsel mehr als die übrigen).","status":"entwurf","kurz":"Aktives Zuhören nimmt zuerst auf, was Alex erlebt: Gefühl benennen, Gehörtes wiedergeben, offen nachfragen. Du musst ihm dafür nicht zustimmen, und so bleibt die Tür offen und du erfährst, was gerade los ist.","prueffrage":"Was schreibt Alex über sich selbst, und was befürchtet er am Ende seiner Nachricht?","rueckmeldung":[{"option":1,"text":"Sorge und Fakten sind gut gemeint, und Faktenchecks können später durchaus ihren Platz haben. Jetzt antworten sie aber auf den Inhalt und überhören den Menschen, und „du verrennst dich“ bestätigt Alex, dass er für verrückt gehalten wird."},{"option":2,"text":"Nähe und „du bist nicht allein“ tun in so einer Lage gut. Doch wer zustimmt, ohne verstanden oder geprüft zu haben, was Alex meint, verwechselt Mitgefühl mit Zustimmung. Verstehen geht auch ohne Einverständnis."},{"option":3,"text":"Schlafmangel und Angst ernst zu nehmen ist richtig, und fachliche Hilfe kann sinnvoll sein. Wird Alex aber sofort weitergereicht, hat ihm noch niemand zugehört, und das Gespräch endet, bevor es begonnen hat."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook (Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kalla & Broockman (2020): Reducing Exclusionary Attitudes through Interpersonal Conversation: Evidence from Three Field Experiments (APSR 114(2), doi 10.1017/S0003055419000923; frei als SocArXiv-Vorabfassung vom 17.01.2020)","oeffentlich":true,"doi":"10.31235/osf.io/2ra9x","seite":"Abstract (S. 1 der Vorabfassung)","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"2a3959a4754a40b8"}},{"id":"qx-h-045","clusterId":"H","werkstueckRef":"H.2.4","stufe":1,"question":"Welche Entscheidung ist hier die klügste?","options":["Das Gespräch ruhig beenden („Wir reden nicht mehr über die Sache, deshalb höre ich hier auf“), weil kein Austausch von Argumenten mehr stattfindet.","Ruhig weiterdiskutieren („Ich bleibe dran“), weil sich Beharrlichkeit in schwierigen Gesprächen auszahlt, sobald der andere merkt, dass man nicht lockerlässt.","Eine klärende Nachfrage stellen („Was genau meinst du damit?“), weil hinter scharfen Aussagen oft ein Missverständnis steckt, das sich so ausräumen lässt.","Weitere Quellen und Zahlen anführen („Dann zeige ich dir die Daten“), weil sich sachliche Streitfragen am besten mit Belegen klären lassen."],"correctIndex":0,"explanation":"Ein Gespräch lebt davon, dass beide auf Argumente eingehen und eine gemeinsame Wirklichkeit anerkennen. Hier wird beides gebrochen: Er greift die Person statt der Sache an und leugnet, was er selbst gesagt hat. Solange das so bleibt, bringt jeder weitere Beitrag nichts, denn es geht ihm nicht mehr ums Überzeugen, und weiteres Mitspielen kostet nur zusätzliche Kraft. Ruhig und begründet auszusteigen schützt deine Energie und lässt dir die Souveränität. Beharrlichkeit lohnt, wenn sich der andere bewegt; hier ist schon der dritte Versuch gescheitert. Nachfragen helfen bei Missverständnissen, aber er beantwortet jede Gegenfrage nur mit Angriffen. Belege nützen nur, wenn Gegenargumente überhaupt zählen, und das tun sie hier nicht.","coreRule":"⚡ Wer das Brett umwirft, spielt nicht mehr Schach: Dann darfst du aufstehen.","beleg":"Werkstück H.2.4 (Die Geschichte; Kernidee; Kontext & Tiefe; Anwendung & Relevanz – Wie man den Ausstieg vollzieht)","status":"entwurf","scenario":"Du diskutierst seit einer Stunde mit einem Bekannten über ein politisches Thema. Auf jede Gegenfrage antwortet er nur noch mit Angriffen auf deine Person („Du hast ja keine Ahnung“). Als du dich auf seine eigene Aussage von vorhin beziehst, behauptet er, das nie gesagt zu haben. Dein Versuch, zur Sache zurückzukehren, scheitert zum dritten Mal. Du bist erschöpft, und das Gespräch dreht sich seit Minuten im Kreis.","quote":"","quoteLabel":"","kurz":"Wenn er die Person statt der Sache angreift und eigene Aussagen leugnet, gibt es keinen Austausch von Argumenten mehr. Mehr Einsatz ändert daran nichts, ruhig und begründet auszusteigen schützt dagegen deine Kraft.","prueffrage":"Geht er mit seinen letzten Antworten noch auf das ein, was du sagst, oder nur auf dich als Person?","rueckmeldung":[{"option":1,"text":"Durchhalten wirkt stark und lohnt sich oft, wenn sich der andere bewegt. Hier sind aber schon drei Versuche gescheitert, ohne dass er sich einen Schritt bewegt hat, und jede weitere Runde kostet nur zusätzliche Kraft."},{"option":2,"text":"Eine Nachfrage kann ein echtes Missverständnis ausräumen. Hier ist aber keines erkennbar: Er beantwortet jede Gegenfrage mit Angriffen und streitet ab, was er gesagt hat, die Nachfrage liefe also ins Leere."},{"option":3,"text":"Belege sind bei Sachfragen meist das beste Mittel. Sie wirken aber nur, wenn Gegenargumente für den anderen überhaupt zählen. Wer Personen angreift und eigene Aussagen leugnet, lässt auch neue Zahlen abprallen."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Petrov, Chan, Lau u. a. (2023): Sunk Cost Effects for Time Versus Money: Replication and Extensions Registered Report of Soman (2001). International Review of Social Psychology 36(1), Art. 17","oeffentlich":true,"doi":"10.5334/irsp.883","url":"https://rips-irsp.com/articles/10.5334/irsp.883","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansen, H. (2015/2024): Fallacies. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Arkes & Blumer (1985): The Psychology of Sunk Cost. Organizational Behavior and Human Decision Processes 35(1) (nicht frei, laut OpenAlex geschlossen; in Landkarte B.6 geprüft)","oeffentlich":false,"doi":"10.1016/0749-5978(85)90049-4"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e3da762ed4a1107c"}},{"id":"qx-h-046","clusterId":"H","werkstueckRef":"H.2.4","stufe":2,"question":"Welcher Abschlusssatz beendet das Gespräch in dieser Lage am besten?","scenario":"Dein Gegenüber wirft dir seit einer Weile Halbwahrheiten im Minutentakt hin, geht auf keinen deiner Punkte ein und wird persönlich. Zwei Versuche, das Gespräch zu beruhigen und zur Sache zurückzuführen, sind gescheitert. Du merkst, dass dich jede weitere Antwort nur Kraft kostet, ohne dass etwas geklärt wird.","options":["„Ich habe das Gefühl, dass dieses Gespräch nicht mehr produktiv ist, weil wir nicht mehr über die Sache, sondern übereinander reden. Ich möchte es hier beenden.“","„Ich sehe, dass es dir gar nicht um eine Klärung geht, sondern nur darum, recht zu behalten. Deshalb beende ich das Gespräch an dieser Stelle.“","„Lass uns eine neutrale dritte Person hinzuziehen, die sich die Fakten ansieht und zwischen uns vermittelt, bevor wir weiter über das Thema reden.“","„Ich antworte dir erst wieder, wenn du dich für deinen Ton bei mir entschuldigt und alle deine bisherigen Punkte ausdrücklich zurückgenommen hast.“"],"correctIndex":0,"explanation":"Ein Gespräch lohnt sich nur, solange beide Seiten sich auf die Sache einlassen; hier geht die andere Seite auf keinen deiner Punkte ein, und zwei Versuche, zur Sache zurückzukehren, sind gescheitert. Der beste Abschlusssatz bleibt ruhig, benennt sachlich den Grund (ihr redet nicht mehr über die Sache, sondern übereinander) und beendet das Gespräch, ohne die Person abzuwerten. Wer dem Gegenüber stattdessen seine Beweggründe unterstellt, spricht über dessen Person und kann sie gar nicht prüfen. Eine Vermittlung kann bei echten Sachfragen helfen, setzt aber voraus, dass beide weitersprechen wollen, und beendet hier nichts. Eine Entschuldigung als Bedingung knüpft das Ende an eine Forderung, statt das Gespräch selbst zu beenden.","coreRule":"⚡ Steige ruhig, bestimmt und begründet aus: Benenne sachlich den Grund, ohne die Person abzuwerten.","beleg":"Werkstück H.2.4 (Wie man den Ausstieg vollzieht: Meta-Kommunikation)","status":"entwurf","kurz":"Zwei Versuche, zur Sache zurückzukehren, sind gescheitert. Der Schlusssatz benennt deshalb ruhig den Grund, nämlich dass ihr nicht mehr über die Sache redet, und beendet das Gespräch, ohne Motive zu unterstellen oder die Person abzuwerten.","prueffrage":"Ist das Gespräch nach deinem letzten Satz wirklich beendet, und was erfährt dein Gegenüber darin über den Grund?","rueckmeldung":[{"option":1,"text":"Das Gespräch zu beenden ist hier richtig, und auch die Ruhe im Ton. Der Satz unterstellt aber ein Motiv, „nur recht behalten“, das du von außen nicht prüfen kannst, und wertet die Person ab statt den Gesprächsverlauf zu benennen."},{"option":2,"text":"Eine neutrale Instanz kann bei echten Sachfragen helfen, wenn beide weitersprechen wollen. Hier geht das Gegenüber aber auf nichts ein; der Satz verlängert das Gespräch, statt es zu beenden."},{"option":3,"text":"Der persönliche Ton ist ärgerlich, und der Wunsch nach einer Entschuldigung verständlich. Der Satz beendet das Gespräch aber nicht, sondern knüpft es an Forderungen, die ein Gegenüber, das nicht auf die Sache eingeht, kaum erfüllen wird."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Rogers, Howieson & Neame (2018): I understand you feel that way, but I feel this way: the benefits of I-language and communicating perspective during conflict. PeerJ 6:e4831","oeffentlich":true,"doi":"10.7717/peerj.4831","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5961625/","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansen, H. (2015/2024): Fallacies. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1bad02cb36a91caa"}},{"id":"qx-h-047","clusterId":"H","werkstueckRef":"H.2.4","stufe":3,"question":"Ein Gespräch über Wohnungspolitik läuft seit einer Stunde. Du hast zweimal ruhig angeboten, zur Sachfrage zurückzukehren. Welche Beobachtung rechtfertigt es am ehesten, das Gespräch jetzt zu beenden?","options":["Er widerspricht dir hartnäckig, bleibt dabei aber sachlich, und dein Argument gerät allmählich unter Druck.","Er hat einmal einen Strohmann benutzt, sich sofort entschuldigt und ist danach auf deinen Einwand sachlich eingegangen.","Dir fehlen gerade die Gegenargumente, und du möchtest das Gespräch beenden, bevor es für dich unangenehm wird.","Er greift dich fortlaufend persönlich an, und deine mehrfachen Versuche, zur Sachebene zurückzukehren, scheitern."],"correctIndex":3,"explanation":"Ein Abbruch ist dann begründet, wenn das Gegenüber nicht mehr nach den Regeln des ehrlichen Diskurses spielt: Unehrliche Mittel wie persönliche Angriffe sind nicht mehr vereinzelte Ausrutscher, sondern die primäre Kommunikationsstrategie, und mehrfache Versuche, das Gespräch auf die sachliche Ebene zurückzuführen, scheitern. Dann ist das Spiel manipuliert, und jeder weitere Beitrag kostet mentale Energie, ohne dass ein echter Austausch von Ideen möglich ist. Sachlicher Widerspruch ist dagegen der Normalfall eines guten Gesprächs, auch wenn er unbequem ist. Ein einzelner Fehler, der sofort korrigiert wird, zeigt gerade Redlichkeit, denn dort ist der Einzelfall kein Dauerzustand. Und eigenes Unbehagen oder fehlende Gegenargumente sind kein Ausstiegsgrund: Ein Ausstieg setzt voraus, dass das Gegenüber systematisch unehrliche Taktiken einsetzt, und nicht, dass das Gespräch für dich selbst schwierig wird.","coreRule":"⚡ Ein Gespräch zu verlassen ist angemessen bei systematischer Unehrlichkeit und gescheiterten Rückführungsversuchen, nicht bei bloßem Unbehagen oder Gegenwind.","beleg":"Werkstück H.2.4 (Anwendung & Relevanz: Wann man den Tisch verlässt; Red Flags)","status":"entwurf","scenario":"Dein Gesprächspartner antwortet auf keinen deiner Punkte inhaltlich. Stattdessen wertet er dich bei jedem Beitrag persönlich ab („Typisch du, du hast ja keine Ahnung“). Deine zwei freundlichen Rückführungen auf die Sache hat er jeweils mit neuen Angriffen beantwortet.","kurz":"Wer dich bei jedem Beitrag persönlich angreift und zweimal auf Rückführungen zur Sache mit neuen Angriffen reagiert, spielt nicht mehr ehrlich. Der Fehler wäre, schon bei Gegenwind oder eigenem Unbehagen auszusteigen, statt auf ein systematisches Muster zu achten.","prueffrage":"Woran erkennst du im Gesprächsverlauf, ob jemand dir nur widerspricht oder ob er gar nicht mehr über die Sache redet?","rueckmeldung":[{"option":0,"text":"Wer hartnäckig widerspricht und dich unter Druck setzt, macht ein Gespräch anstrengend, aber nicht unredlich. Sachlicher Widerspruch gehört zum Normalfall eines guten Gesprächs, auch wenn er unbequem ist, und ist für sich noch kein Grund aufzuhören."},{"option":1,"text":"Ein Strohmann ist ein unfairer Zug, hier aber ein einzelner Ausrutscher. Er wurde sofort zurückgenommen, und danach ging er auf deinen Einwand ein. Das spricht für Redlichkeit, nicht für ein manipuliertes Gespräch."},{"option":2,"text":"Fehlende Gegenargumente sind unangenehm, sagen aber nichts über das Verhalten des anderen. Ein Abbruch ist begründet, wenn das Gegenüber systematisch unehrlich vorgeht, nicht schon, wenn das Gespräch für dich selbst schwierig wird."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Hansen, H. (2015/2024): Fallacies. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d8340b9633711c4e"}},{"id":"qx-h-048","clusterId":"H","werkstueckRef":"H.2.4","stufe":4,"question":"Was ist an dieser Antwort deines Cousins das eigentliche Problem für ein sinnvolles Gespräch?","scenario":"Dein Cousin antwortet auf jeden Beleg: „Genau das sagen sie ja, damit wir es nicht merken. Dein Beleg ist Teil der Vertuschung.“","options":["Er beruft sich auf eine Autorität statt auf Belege, sodass seine Behauptung nur auf Ansehen beruht.","Er wertet jeden Gegenbeweis als Teil der Verschwörung, sodass nichts ihn mehr widerlegen könnte.","Er verallgemeinert aus einem Einzelfall auf alle Fälle, sodass seine Schlussfolgerung auf dünner Basis steht.","Er verweist darauf, dass viele seine Ansicht teilen, sodass die Zahl der Anhänger als Beweis dient."],"correctIndex":1,"explanation":"Eine Behauptung, die jeden Gegenbeweis als Beweis für die Verschwörung umdeutet, lässt sich durch nichts mehr widerlegen. Dann ist kein echter Austausch von Ideen mehr möglich: Weitere Belege kosten dich nur Zeit und Energie. Ein ruhiger, begründeter Ausstieg („Wir kommen hier nicht weiter, lass uns das Thema beenden.“) ist dann die vernünftigere Wahl, als weiter zu argumentieren. Die anderen Gedanken benennen echte Denkfehler, die dein Cousin hier aber nicht begeht: Er beruft sich auf keine Autorität, sondern wehrt deinen Beleg ab. Er schließt auch nicht von einem Einzelfall auf alle Fälle. Und er verweist nicht auf eine Mehrheit, sondern erklärt jeden Beleg im Voraus für wertlos.","coreRule":"⚡ Wo jeder Beleg zum Beweis für die Verschwörung wird, ist das Spiel versiegelt: Dann hilft nur der ruhige Ausstieg.","beleg":"Werkstück H.2.4 (Anwendung & Relevanz: ‚Wenn der Verschwörungsmythos sich versiegelt‘)","status":"entwurf","kurz":"Wer jeden Beleg zum Teil der Vertuschung erklärt, hat sich gegen jede Widerlegung abgedichtet. Dann bringt weiteres Argumentieren nichts mehr, und ein ruhiger Ausstieg ist vernünftiger, als dem Gespräch noch mehr Energie zu opfern.","prueffrage":"Was hat dein Cousin auf deine bisherigen Belege geantwortet, und hing seine Antwort davon ab, was im jeweiligen Beleg stand?","rueckmeldung":[{"option":0,"text":"Berufungen auf Autoritäten sind tatsächlich ein verbreiteter Fehler, und Belege zu verlangen ist richtig. Dein Cousin nennt aber gar keine Autorität. Er wehrt deine Belege ab, indem er sie im Voraus für wertlos erklärt."},{"option":2,"text":"Ein Schluss vom Einzelfall auf alle Fälle ist ein klassischer Denkfehler. Hier geht es aber nicht um einen Einzelfall, von dem er ausgeht. Er deutet jeden Beleg pauschal um, und das Problem liegt in dieser Umdeutung."},{"option":3,"text":"Dass viele etwas glauben, ist ein schwaches Argument. Dein Cousin sagt aber nichts über die Zahl seiner Anhänger. Sein Problem ist, dass er jeden Beleg schon vorab zur Vertuschung erklärt."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook (Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c0f10addcc813dfc"}}]`);export{t as n,n as t};